window.I18N_LANG="vi";window.I18N_ROOT="../";window.I18N_UI=Object.assign(window.I18N_UI||{},{"🔎 전체": "🔎 Tất cả", "📌 기타": "📌 Khác", "이 묶음에는 없어요 🙈": "Không có trong nhóm này 🙈", "다른 묶음에 {n}가 있어요.": "Có {n} ở nhóm khác.", "개": "", "전체에서 보기": "Xem tất cả", "\"{q}\"에 대한 검색 결과가 없습니다.": "Không có kết quả cho \"{q}\".", "다른 키워드로 검색하거나, 아래 톡톡으로 문의해 주세요.": "Hãy thử từ khác, hoặc hỏi chúng tôi qua TalkTalk bên dưới.", "이 묶음에는 아직 질문이 없어요.": "Nhóm này chưa có câu hỏi nào.", "{n}의 질문을 찾았습니다.": "Đã tìm thấy {n} câu hỏi.", "🔗 이 질문 링크 복사": "🔗 Sao chép liên kết câu hỏi này", "✓ 복사됐어요": "✓ Đã sao chép", "주소": "Liên kết", "FAQ가 없습니다.": "Không có câu hỏi nào.", "FAQ를 불러오지 못했습니다.": "Không tải được câu hỏi.", "설명 그림": "Hình minh họa", "렌즈 모양 아이콘": "Biểu tượng ống kính", "(한국어)": "(Chỉ tiếng Hàn — đang chuẩn bị bản dịch)"});window.I18N_PIN={"hoàn": 70};window.I18N_FAQ={"items": {"4": {"h": "h0y8oc", "q": "Máy in đa năng bị hỏng khi tôi đang dùng.", "a": "📞 Hãy liên hệ số điện thoại ghi trong cửa hàng, hoặc qua Naver TalkTalk.\n\n⏰ Gọi điện: ngày thường (thứ 2–thứ 6) 9 giờ sáng–9 giờ tối\n🚫 Thứ 7, Chủ nhật và ngày lễ không tư vấn qua điện thoại.\n💬 Ngoài giờ đó và thứ 7·Chủ nhật·ngày lễ: hãy gửi 4 điều sau qua Naver TalkTalk.\n1. Tên cửa hàng (ghi trên màn hình nền máy tính hoặc bảng thông báo cạnh máy tính)\n2. Số máy in đa năng\n3. Lỗi gặp phải\n4. Số liên lạc\nChúng tôi sẽ liên hệ sau khi kiểm tra.\n\n🙋 Nếu đã liên hệ mà chưa có trả lời, hãy đăng ký hoàn tiền bằng biểu tượng [환불신청] (Đăng ký hoàn tiền) trên màn hình nền máy tính và quay lại vào ngày khác.\n⏰ Phải đăng ký hoàn tiền trong vòng 5 ngày kể từ ngày xảy ra sự cố (tính cả thứ Bảy, Chủ nhật và ngày lễ). Chỉ những đăng ký trong 5 ngày mới được kiểm tra và xử lý. Quá hạn sẽ không được hoàn tiền.\n\n⚠️ Dù thanh toán xong mà không in ra, tuyệt đối đừng thanh toán lại!\nTệp lớn có thể mất hơn 10 phút mới in ra. Nếu trong lúc bạn thanh toán lại mà bản in trước đó in ra, sẽ không được hoàn tiền. Nhất định phải liên hệ trước."}, "15": {"h": "8tov0n", "q": "Tôi đã thanh toán nhưng không in ra.", "a": "⛔ Đừng thanh toán lại cho cùng một tệp!\n\n1. ⏳ Hãy chờ khoảng 10 phút.\n2. 📞 Nếu sau 10 phút vẫn không được, hãy gửi tên cửa hàng và sự cố qua Naver TalkTalk. (Điện thoại chỉ nghe ngày thường 9 giờ sáng–9 giờ tối)\n   Ví dụ) \"Cửa hàng Gwanggyo, máy số 1: đã thanh toán mà sau 10 phút vẫn không in ra\"\nQuản lý sẽ liên hệ sau khi kiểm tra.\n\n🐢 Tại sao chậm?\n- Tệp lớn.\n- Máy in đa năng chậm.\n- Mạng của cửa hàng tạm thời chậm.\n\n🚀 Cách in nhanh hơn (cửa hàng có 2 hoặc 3 máy tính)\n- Cửa hàng có 2 máy tính: làm ở PC1 thì thanh toán ở máy số 2, làm ở PC2 thì thanh toán ở máy số 1.\n- Cửa hàng có 3 máy tính: làm ở PC1·PC2 thì thanh toán ở máy số 2, làm ở PC3 thì thanh toán ở máy số 1.\n\n🌙 Nếu thanh toán vào giờ không có tư vấn điện thoại (ngày thường 9 giờ tối–9 giờ sáng, thứ 7, Chủ nhật, ngày lễ) mà không in ra và TalkTalk chưa trả lời ngay, cũng đừng thanh toán lại. Hãy đăng ký [환불신청] (Đăng ký hoàn tiền), hôm sau quản lý sẽ liên hệ.\n\n⏰ Bản in có thể ra sau 10 phút. Dù bận, hãy chờ trong cửa hàng đủ 10 phút.\n\n📝 Đăng ký hoàn tiền: biểu tượng [환불신청] (Đăng ký hoàn tiền) trên màn hình nền máy tính cửa hàng\n⏰ Phải đăng ký hoàn tiền trong vòng 5 ngày kể từ ngày xảy ra sự cố (tính cả thứ Bảy, Chủ nhật và ngày lễ). Chỉ những đăng ký trong 5 ngày mới được kiểm tra và xử lý. Quá hạn sẽ không được hoàn tiền.\n\n👀 Cách biết máy có đang in không\n- Nếu phía trên màn hình máy có biểu tượng máy in, máy đang chuẩn bị in.\n- Nếu đèn ở giữa phía dưới màn hình nhấp nháy, máy đang in.\n- Lúc này hãy chờ.\n\n⚠️ Nếu rời cửa hàng mà không liên hệ, sau này sẽ khó hoàn tiền."}, "2": {"h": "11ozofa", "q": "Tôi đã gửi tệp nhưng không thấy tệp trên máy in đa năng.", "a": "Nếu bạn đã nhập mã PIN ở máy in đa năng mà thấy '검색된 인쇄 작업이 없습니다' (Không tìm thấy lệnh in), hãy xem bên dưới.\n[[img:images/faq/print-nojob.png]]\n\nHãy xem cửa sổ danh sách lệnh in [흑백출력] (đen trắng) / [컬러출력] (màu) trên máy tính.\n👀 Nếu danh sách vẫn còn, tệp vẫn đang trên đường đến máy in đa năng.\n⚠️ Nếu danh sách bị kẹt mãi, sẽ không tìm thấy ở máy in đa năng.\n\nHãy thử như sau.\n1. ⏳ Nếu tệp lớn, hãy chờ một chút.\n2. 🔄 Nếu vẫn không được, khởi động lại máy tính rồi in lại.\n3. 🔢 Kiểm tra mã PIN nhập ở máy in đa năng có giống mã PIN đã nhập trên máy tính không.\n\n🗑️ Tệp sẽ tự động bị xóa 30 phút sau khi gửi."}, "16": {"h": "lfosuk", "q": "Bị kẹt giấy khi đang in hoặc photo.", "a": "⛔ Đừng kéo tờ giấy bị kẹt ra!\nMực chưa khô nên có thể dính vào tay. Cửa hàng không có khăn giấy.\n\n1. Để nguyên tờ giấy, rồi đăng ký [환불신청] (Đăng ký hoàn tiền) trên màn hình nền máy tính.\n2. Nếu là A4: gửi lệnh in lại từ máy tính, rồi thanh toán và in ở máy bên cạnh.\n3. Nếu là B4, A3: trước tiên hãy gửi nội dung qua Naver TalkTalk và chờ quản lý trả lời có cách xử lý không.\n   Nếu quản lý trả lời không có cách xử lý, rất xin lỗi, hãy đăng ký hoàn tiền và quay lại vào hôm sau.\n\n⏰ Phải đăng ký hoàn tiền trong vòng 5 ngày kể từ ngày xảy ra sự cố (tính cả thứ Bảy, Chủ nhật và ngày lễ). Chỉ những đăng ký trong 5 ngày mới được kiểm tra và xử lý. Quá hạn sẽ không được hoàn tiền."}, "17": {"h": "h35u2p", "q": "Tôi đã chọn máy in màu nhưng lại in ra đen trắng.", "a": "🎨 Muốn in màu, hãy luôn kiểm tra 3 điều này.\n1. Ở màn hình in, chọn máy in [컬러출력] (màu).\n2. Ở bản xem trước, kiểm tra tất cả các trang đều có màu.\n3. Ở màn hình giá tiền của máy in đa năng, kiểm tra lại một lần nữa có phải [컬러] (màu) không.\n\n❌ Những trường hợp không được hoàn tiền\n- Không chọn máy in màu, nhưng nghĩ sẽ in màu vì bản xem trước có màu.\n- Không nhớ bản xem trước là màu hay đen trắng.\n- Đã chọn máy in màu nên nghĩ sẽ in màu dù bản xem trước là đen trắng.\n- Đã xem bản xem trước nhưng một số trang trong nhiều trang in ra đen trắng.\n- Đã chọn máy in màu và xem bản xem trước nhưng in ra đen trắng. (Nhầm màn hình chỉnh sửa với bản xem trước)\n- Đã chọn máy in đen trắng nhưng nghĩ sẽ in màu vì bản xem trước có màu. (Cũng không xem màn hình giá tiền)\n\n💸 Trường hợp đã chọn máy in màu mà in ra đen trắng\n- Chúng tôi hủy một phần thanh toán: tổng tiền trừ đi giá đen trắng.\n- Hãy đăng ký hoàn tiền và gửi ảnh bản in đen trắng qua Naver TalkTalk.\n- Phải đăng ký hoàn tiền trong vòng 5 ngày kể từ ngày xảy ra sự cố (tính cả thứ Bảy, Chủ nhật và ngày lễ). Chỉ những đăng ký trong 5 ngày mới được kiểm tra và xử lý. Quá hạn sẽ không được hoàn tiền.\n- Nếu tệp đã bị sửa hoặc gửi tệp khác, chúng tôi không xử lý.\n- Nếu không đồng ý cách này mà yêu cầu hoàn toàn bộ tiền, sẽ không được hoàn tiền.\n- Nếu đã chọn máy in đen trắng và thanh toán, in đen trắng là đúng nên không được hoàn tiền.\n\n📖 Bấm vào đây để xem hướng dẫn bằng hình.\n[[go:guide-print.html#ptips|Xem cách kiểm tra màu ở bản xem trước]]"}, "18": {"h": "1tczehm", "q": "Bản in bị sọc hoặc lem màu. Có được hoàn tiền không?", "a": "Chỉ 4 trường hợp lỗi sọc·màu·hình dạng dưới đây được hoàn tiền. (In ra giấy trắng, kẹt giấy, v.v. hãy xem các câu hỏi liên quan.)\n\n✅ Được hoàn tiền\n1. Xuất hiện một sọc trắng dài. (ngang hoặc từ trên xuống dưới)\n2. Màu bị lem.\n3. Một màu mà in ra giống như chuyển màu (gradient).\n4. Hình hình học không liên quan đến bản gốc bị in khắp trang.\n\n📝 Cách hoàn tiền\nĐể lại bản in ở cửa hàng và đăng ký bằng biểu tượng [환불신청] (Đăng ký hoàn tiền) trên màn hình nền máy tính.\n⚠️ Nếu không để lại bản in, sẽ không được hoàn tiền.\n⚠️ Nếu không bấm biểu tượng [환불신청] (Đăng ký hoàn tiền) và điền nội dung để đăng ký, sẽ không xử lý hoàn tiền được.\n⏰ Phải đăng ký hoàn tiền trong vòng 5 ngày kể từ ngày xảy ra sự cố (tính cả thứ Bảy, Chủ nhật và ngày lễ). Chỉ những đăng ký trong 5 ngày mới được kiểm tra và xử lý. Quá hạn sẽ không được hoàn tiền.\n\n❌ Không được hoàn tiền\n1. Màu khác với màn hình máy tính. (tối hơn, xỉn, xanh nhạt trông như xanh đậm, v.v.)\n2. Photo cùng một bản gốc màu mà mỗi lần màu lại khác.\n   → Dù cùng bản gốc, mỗi lần photo màu có thể khác. Màu khác với bản gốc không được hoàn tiền vì bất kỳ lý do gì.\n3. In cùng một tệp nhiều lần mà màu khác nhau. (Dù cùng tệp, màu vẫn có thể khác.)\n4. Là tệp Hangul mà màu dạ quang không in ra. (Trình xem Hangul không có chức năng bút dạ quang.)\n5. Photo mà hình mờ (watermark) của bản gốc không ra. (Hình mờ rất nhạt nên photo không ra.)\n6. Photo giấy khen mà màu vàng·bạc trông lạ. (Màu ánh kim không thể hiện được và sẽ ra màu tối.)\n7. Photo một tờ đã được in một lần mà một phần không ra.\n   → Đừng photo lại giấy đã in hoặc đã photo. Sẽ bị mờ và không ra.\n8. Là PDF làm trên iPad mà không in ra màu.\n   → Trong Acrobat Reader, xem trước với [컬러출력] (màu) sẽ không thấy màu. Vì không kiểm tra bản xem trước nên không được hoàn tiền.\n   → PDF iPad hãy kéo vào Edge hoặc Chrome và bấm [인쇄] (In). Kiểm tra ở bản xem trước tất cả các trang đều có màu rồi mới in.\n9. Là PDF làm bằng chương trình thiết kế web như Canva mà không in ra màu.\n   → Vì không kiểm tra bản xem trước nên không được hoàn tiền.\n   → Hãy mở bằng Edge hoặc Chrome và bấm [인쇄] (In). Kiểm tra ở bản xem trước tất cả các trang đều có màu rồi mới in.\n10. Chữ viết bằng bút chì in ra mờ hoặc không ra.\n11. Tài liệu làm bằng cách scan bị mờ, hoặc màu dạ quang·màu trong suốt không ra.\n12. In nhiều bản cùng một bản gốc mà vị trí nội dung hơi khác nhau. (Đây là điều xảy ra ở máy đưa từng tờ giấy một)\n13. Giấy có chấm nhỏ (vết lốm đốm). (Đó là do quá trình làm giấy nên không phải lỗi)"}, "66": {"h": "1145m9y", "q": "Tôi in/photo màu nhưng màu khác với màn hình (bản gốc). Có phải máy hỏng không?", "a": "Hầu hết không phải máy hỏng. Màn hình tạo màu bằng ánh sáng (RGB), còn máy in tạo màu bằng 4 màu mực (CMYK), nên màu trên màn hình và trên giấy không thể giống hệt nhau.\n\n■ Màu đặc biệt khác khi\n· Màu tươi như đỏ·xanh dương·tím·xanh lá, màu dạ quang, màu vàng·bạc\n· Cùng một tệp nhưng mỗi trang·mỗi tờ lại khác (nhất là PDF làm bằng công cụ thiết kế web như Canva·Miricanvas, PPT, ghi chú iPad)\n· Khi photo: nhũ vàng·nhũ bạc ra tối, màu dạ quang ra mờ hoặc không ra. Màu nhạt (hình mờ) có thể bị mất, photo lại bản đã in có thể chỉ còn màu đậm. Giấy tờ có hoa văn chống sao chép như bản sao hộ khẩu·giấy chứng nhận có thể hiện hoa văn như chữ \"사본\" (Bản sao).\n· Bút dạ quang trong tệp Hangul không in ra được bằng trình xem Hangul của cửa hàng.\n\n■ Hãy thử thế này\n1. Mở PDF bằng Chrome·Edge, xem trước tất cả các trang rồi mới in\n2. Mang tệp JPG thay vì PDF để in (chữ có thể hơi kém sắc nét)\n※ Đây là cách tăng khả năng giảm chênh lệch màu. Không ra giống 100%.\n\n■ Tiêu chuẩn hoàn tiền cho lỗi màu khi in màu (không có ngoại lệ)\nChỉ hoàn tiền 3 trường hợp: bị sọc · lem màu · một màu in ra thành chuyển màu. Các chênh lệch màu khác không được hoàn tiền hay in lại.\n\n[[img:images/faq/color-notice-poster2.jpg]]"}, "47": {"h": "9hh84o", "q": "Bản in ra giấy trắng (trang trống).", "a": "📄 In ra giấy trắng thường có hai lý do.\n\n1️⃣ Bản xem trước không có nội dung\n- Trước khi in, nhất định kiểm tra ở bản xem trước tất cả các trang đều có nội dung.\n- Nếu bản xem trước trắng trơn, sẽ in ra giấy trắng.\n\n2️⃣ Mở và in thẳng từ USB\n- Tệp trong USB phải lưu vào máy tính rồi mới mở và in.\n- Tệp nén phải giải nén rồi mới mở.\n\n🔁 Hãy in lại như sau\n\n📌 Là tệp PDF làm bằng công cụ thiết kế web như Canva·Miricanvas\n1. Mở Chrome hoặc Edge và kéo tệp thả vào cửa sổ đó. (Hoặc bấm chuột phải vào tệp, chọn Edge·Chrome trong [연결 프로그램] (Mở bằng).)\n2. Bấm [인쇄] (In).\n3. Kiểm tra ở bản xem trước tất cả các trang đều có nội dung.\n4. Nếu thấy đủ nội dung thì in.\n\n📌 Là tệp PDF nhưng không biết làm ở đâu\n1. Mở Chrome hoặc Edge và kéo tệp thả vào cửa sổ đó, hoặc bấm chuột phải vào tệp, chọn Edge·Chrome trong [연결 프로그램] (Mở bằng) để mở. Hầu hết lỗi màu lạ hoặc in ra giấy trắng sẽ được khắc phục.\n2. Kiểm tra ở bản xem trước tất cả các trang đều có nội dung.\n3. Nếu thấy đủ nội dung thì in lại.\n\n💸 Giấy in ra trắng thì hãy đăng ký hoàn tiền\n1. Nếu mang tờ giấy trắng đi hoặc không để đúng chỗ được hướng dẫn, có thể không được hoàn tiền. Chúng tôi cần kiểm tra có thật là in ra trắng không.\n2. Hãy để tờ giấy trắng gọn gàng ở chỗ xếp giấy.\n3. Bấm biểu tượng [환불신청] (Đăng ký hoàn tiền) trên màn hình nền máy tính cửa hàng để đăng ký hoàn tiền.\n4. Quản lý kiểm tra, nếu đủ điều kiện sẽ xử lý, và báo kết quả qua số điện thoại bạn ghi khi đăng ký.\n\n⏰ Phải đăng ký hoàn tiền trong vòng 5 ngày kể từ ngày xảy ra sự cố (tính cả thứ Bảy, Chủ nhật và ngày lễ). Chỉ những đăng ký trong 5 ngày mới được kiểm tra và xử lý. Nếu không đăng ký hoặc đăng ký sau 5 ngày, sẽ không được hoàn tiền.\nℹ️ Đăng ký không có nghĩa là được hoàn tiền ngay. Quản lý kiểm tra rồi chỉ xử lý trường hợp đủ điều kiện.\n\n📖 Muốn biết cách mở bằng Chrome·Edge và kiểm tra bản xem trước, hãy bấm vào đây.\n[[go:guide-print.html#browser|Xem cách in bằng Chrome · Edge]]"}, "69": {"h": "xup35h", "q": "Bản photo ra giấy trắng (trang trống).", "a": "🔄 Nếu đặt bản gốc sai hướng, có thể ra giấy trắng.\n\n📌 ADF (khay nạp bản gốc tự động) là 'chỗ đặt bản gốc' ở phía trên máy in đa năng.\n[[sm:images/common/adf-feeder.jpg]]\nCó hai chỗ đặt bản gốc, mỗi chỗ có hướng đặt khác nhau.\n\n📄 1. Khi đặt vào ADF (chỗ đặt bản gốc phía trên máy)\n→ Đặt mặt có nội dung hướng lên trên.\n\n📘 2. Khi đặt lên mặt kính\n→ Mở nắp phía trên của máy in đa năng.\n→ Đặt mặt có nội dung úp xuống mặt kính. (Ngược với ADF!)\n\n⚠️ Nếu ra giấy trắng do bạn đặt sai, có thể không được hoàn tiền.\n\n✅ Nếu đã đặt đúng như trên mà vẫn ra giấy trắng, có thể máy có vấn đề. Hãy đăng ký hoàn tiền.\nQuản lý kiểm tra, chỉ xử lý trường hợp được xác nhận đủ điều kiện, và báo kết quả qua số liên lạc đã đăng ký.\nĐăng ký hoàn tiền không có nghĩa là được hoàn tiền ngay.\n⏰ Phải đăng ký trong vòng 5 ngày kể từ ngày xảy ra sự cố (tính cả thứ Bảy, Chủ nhật và ngày lễ). Chỉ những đăng ký trong 5 ngày mới được kiểm tra và xử lý.\n\n👇 Hãy đăng ký hoàn tiền bằng hình bên dưới.\n[[btn:images/faq/btn-refund2.png|https://fax.printnuri.com/refund|Đi đăng ký hoàn tiền]]\n💻 Trên màn hình nền máy tính cửa hàng cũng có biểu tượng [환불신청] (Đăng ký hoàn tiền). Có thể đăng ký ở đó.\n\n📖 Bấm vào đây để xem hướng dẫn bằng hình.\n[[go:guide-copy.html#adf|Xem cách dùng khay nạp bản gốc (ADF)]]\n[[go:guide-copy.html#glass|Xem cách đặt bản gốc lên mặt kính]]"}, "48": {"h": "1bwd6hc", "q": "Máy in đa năng hiện thông báo kiểu 'Không có giấy phù hợp trong khay'.", "a": "Dù máy có giấy vẫn có thể hiện thông báo này. Cần sửa cài đặt in rồi gửi lại.\n\n🔎 Kiểm tra trước\nTrong danh sách trên máy, mục [크기] (Khổ) có ghi 'Custom' hoặc 'Letter' thay vì A4·B4·A3 không?\n\n🛠️ Cách sửa\n- PDF: trong cài đặt in, bỏ dấu chọn ở 'PDF 페이지 크기에 따라 용지 소스 선택' (chọn nguồn giấy theo khổ trang PDF). Rồi chọn khổ giấy bạn muốn.\n- Hangul·Word, v.v.: [인쇄] (In) → [컬러출력] (màu) hoặc [흑백출력] (đen trắng) → [속성] (Thuộc tính) → ở thẻ [용지] (Giấy), chọn 'khổ bản gốc' và 'khổ in ra' giống nhau (ví dụ A4).\n\n⛔ Đừng đổi loại giấy (giấy dày, giấy cao cấp, giấy màu, v.v.) trong cài đặt in.\nNếu đổi, sẽ hiện thông báo kiểu 'Hãy cho giấy vào khay đa năng' và không in được.\n\n🖼️ Đừng chọn nhiều ảnh (hình) rồi in bằng chuột phải.\nHãy lưu vào máy tính, rồi mở từng ảnh bằng [알씨] (ALSee) để in.\n\n🔁 Nếu đang in bình thường mà giữa chừng hiện thông báo này, hãy xem câu hỏi dưới đây.\n👉 \"Đã thanh toán và đang in bình thường, bỗng hiện 'không có giấy' và không in được.\"\n\n📖 Bấm vào đây để xem hướng dẫn bằng hình.\n[[go:guide-print.html#acrobat|Xem cài đặt in PDF]]\n[[go:guide-print.html#hancom|Xem cài đặt in Hangul]]\n[[go:guide-print.html#office|Xem cài đặt in Word · Excel · PowerPoint]]"}, "49": {"h": "1tvh6zb", "q": "Thanh toán bằng thẻ không được.", "a": "1. 💳 Lật thẻ sao cho đầu có chip IC cắm vào, rồi cắm lại.\n2. 💳 Thử thẻ khác.\n3. 🖨️ Tìm lại mã PIN ở máy in đa năng bên cạnh rồi thanh toán.\n\n📱 Samsung Pay thì chỉ cần áp vào máy quẹt thẻ.\nNếu vẫn không được, hãy báo qua TalkTalk. (Ngày thường 9 giờ sáng–9 giờ tối có thể gọi điện) (tên cửa hàng, số máy)"}, "50": {"h": "k6st6p", "q": "Màn hình máy tính bị đen hoặc chuột không di chuyển.", "a": "😊 Đừng lo. Hãy làm theo thứ tự sau.\n\n1. 🔘 Nhấn giữ nút nguồn máy tính. Giữ đến khi màn hình tắt hẳn.\n2. Khi màn hình tắt hẳn và không thấy con trỏ chuột là máy đã tắt.\n3. ⏳ Để yên một lúc.\n4. Chỉ bấm nút nguồn một lần để bật lại.\n5. Chờ đến khi màn hình nền hiện ra.\n\n💡 Nếu bật lên mà màn hình không lên, hãy nhấn giữ nút nguồn lần nữa để tắt hẳn, rồi bấm một lần để bật.\n🖥️ Nếu bật lại vẫn vậy, hãy dùng máy tính khác.\n\n📞 Và hãy báo qua TalkTalk. Quản lý sẽ kiểm tra máy tính từ xa.\n- Nội dung cần gửi: tên cửa hàng, số máy tính (ví dụ: cửa hàng Gwanggyo, máy tính số 2)"}, "51": {"h": "nco5pa", "q": "Máy ép màu đen không bật lên được.", "a": "⚫ Máy ép màu đen (PL-1506) bình thường cũng có đèn đỏ nhấp nháy ở 'POWER'.\n\n1. Nếu đèn đỏ không nhấp nháy là hoàn toàn không có điện. Hãy gạt công tắc nguồn ở mặt sau bên phải máy ép sang bên để cấp điện.\n2. Nếu đèn POWER sáng, bấm nút [전원] (Nguồn) → nút [문서] (Tài liệu).\n3. Khi đèn xanh ở 'READY' nhấp nháy rồi ngừng sau khoảng 1 phút là đã làm nóng xong.\n4. Cho giấy in vào túi ép, rồi đưa từ từ vào khe, đầu kín trước.\n\n⚠️ Chỉ cho túi ép rỗng, hoặc chỉ cho giấy mà không có túi ép có thể làm hỏng máy. Hãy làm theo hướng dẫn.\n\n📖 Bấm vào đây để xem hướng dẫn bằng hình.\n[[go:guide-coat.html#pl1506|Xem cách dùng máy ép màu đen (PL-1506)]]"}, "52": {"h": "15cuo1n", "q": "Hình như ép plastic không được tốt.", "a": "💡 Nếu thấy có gì lạ, hãy báo cho chúng tôi trước!\n\n1. Nếu đã làm nóng rồi ép mà có vẻ không được tốt, đừng tiếp tục ép thứ khác.\n2. Hãy gửi tên cửa hàng và \"Đã làm nóng rồi ép nhưng có vẻ không được tốt\" qua Naver TalkTalk.\n3. Nếu mô tả cụ thể tình trạng, chúng tôi có thể tìm ra vấn đề và hướng dẫn cách xử lý nhanh hơn.\n4. Quản lý sẽ kiểm tra tin nhắn TalkTalk và trả lời.\n\n💡 Nếu không biết có vấn đề mà vẫn tiếp tục ép, chúng tôi chỉ có thể kiểm tra lần đầu tiên. Vì vậy hãy báo ngay.\nℹ️ Ép plastic·đóng sách là tự phục vụ. Nếu không làm được vì máy hỏng, chúng tôi hoàn tiền túi ép, bìa đóng nhiệt chưa dùng.\n\n📖 Bấm vào đây để xem hướng dẫn bằng hình.\n[[go:guide-coat.html#coat|Xem cách ép plastic]]"}, "53": {"h": "lpbr6c", "q": "Giấy trong cuốn đóng nhiệt bị rơi ra.", "a": "Thường là do một trong những lý do sau. Những trường hợp này không được hoàn tiền.\n- Giấy in không chạm đều vào lớp keo trắng bên trong bìa.\n- Không đẩy bìa vào sâu hết trong máy đóng sách.\n- Lấy ra mà không để nguội từ 10 phút trở lên đã mở ra. (Mở trước khi keo cứng thì giấy sẽ rơi ra)\n\n✅ Thứ tự đúng\nLàm nóng (khoảng 3 phút, tiếng bíp) → cho giấy ngay ngắn vào bìa → đẩy vào sâu hết → bấm hẹn giờ (khoảng 1 phút) → khi đèn ngừng thì lấy ra cẩn thận → để nguội từ 10 phút trở lên → mở ra\n\n🤔 Nếu không đồng ý, hãy đăng ký hoàn tiền. Quản lý sẽ kiểm tra và báo riêng có hoàn tiền hay không.\n⏰ Phải đăng ký hoàn tiền trong vòng 5 ngày kể từ ngày xảy ra sự cố (tính cả thứ Bảy, Chủ nhật và ngày lễ). Chỉ những đăng ký trong 5 ngày mới được kiểm tra và xử lý. Quá hạn sẽ không được hoàn tiền.\n💡 Nếu không đóng được vì máy hỏng, chỉ hoàn tiền bìa đóng nhiệt đã thanh toán.\n\n📖 Bấm vào đây để xem hướng dẫn bằng hình.\n[[go:guide-bind.html#bind|Xem cách đóng sách nhiệt]]"}, "11": {"h": "wf4g01", "q": "Tôi đã chọn màu nhưng vài trang ở giữa lại in ra đen trắng.", "a": "Đây là lỗi xảy ra với PDF làm bằng Canva và các công cụ tương tự.\n\n👉 Hãy thử mở bằng Chrome hoặc Edge rồi in.\n1) Trước tiên mở Chrome hoặc Edge, rồi kéo tệp thả vào cửa sổ đó.\n2) Hoặc bấm chuột phải vào tệp, chọn Edge·Chrome trong [연결 프로그램] (Mở bằng).\n👀 Trước khi in, kiểm tra ở bản xem trước tất cả các trang đều có màu.\n\n📖 Bấm vào đây để xem hướng dẫn bằng hình.\n[[go:guide-print.html#browser|Xem cách in bằng Chrome · Edge]]"}, "8": {"h": "vgbuap", "q": "Tôi bấm [인쇄] (In) trên máy thì hiện [PC]. Có bấm được không?", "a": "✅ Đúng rồi, bạn đang làm đúng!\nNghĩa là tệp cần in nằm trong máy tính.\n👉 Hãy bấm nút tròn [PC].\n\n📖 Bấm vào đây để xem hướng dẫn bằng hình.\n[[go:guide-print.html#mfp|Xem cách in ở máy in đa năng]]"}, "22": {"h": "4zt91d", "q": "Tôi muốn in tệp trong điện thoại.", "a": "📱 Tệp trong điện thoại hãy nhận bằng cách đăng nhập KakaoTalk bản PC bằng mã QR.\n📧 Cũng có thể gửi qua email để nhận. Nhưng ở cửa hàng khó hướng dẫn cách gửi email từ điện thoại, hãy tìm hiểu trước khi đến.\n\n📲 Cách đăng nhập KakaoTalk bản PC bằng mã QR\n1. Mở KakaoTalk trên máy tính cửa hàng và bấm nút [QR코드 로그인] (Đăng nhập bằng mã QR).\n[[img:images/print/kakao-qr-1.png]]\n2. Mã QR sẽ hiện trên màn hình máy tính. Hãy quét bằng điện thoại trước khi hết giờ.\n[[img:images/print/kakao-pc-qr.png]]\n3. Mở KakaoTalk trên điện thoại và bấm [···(더보기)] (Thêm) ở góc dưới cùng bên phải. (Quan trọng nhất!) Bấm biểu tượng ống kính [[ico:images/print/kakao-lens.png]] ở phía trên, rồi quét mã QR trên màn hình máy tính.\n[[img:images/print/kakao-phone-scan4.png]]\n4. Khi điện thoại hiện màn hình 'Đăng nhập bằng mã QR', bấm [1회용 인증하기] (Xác thực một lần).\n[[img:images/print/kakao-once.png]]\n5. Cửa sổ 'Xác thực bảo mật' trên máy tính sẽ hiện 4 chữ số (mã xác thực). Nhập 4 số đó vào màn hình 'Xác thực bảo mật' trên điện thoại rồi bấm [확인] (Xác nhận). KakaoTalk trên máy tính sẽ được đăng nhập.\n[[img:images/print/kakao-auth.png]]\n6. Lưu tệp bạn đã gửi vào 'Trò chuyện với chính mình' trên điện thoại vào máy tính, rồi mở và in.\n\n⚠️ Dùng xong nhất định phải [로그아웃] (Đăng xuất)! Đừng đánh dấu 'Tự động đăng nhập'. KakaoTalk của bạn có thể bị khách sau nhìn thấy.\n💻 Dùng xong hãy tắt máy tính.\n- Tốt nhất là tắt máy ngay sau khi dùng. Nếu quên, máy sẽ tự tắt sau 10 phút nếu không ai dùng.\n- Nếu đi mà không tắt máy, khách sau có thể dùng ngay trước khi máy tự tắt. Nếu được, hãy tắt máy rồi mới đi.\n- Nếu đã mở trang web quan trọng hoặc tài liệu có thông tin cá nhân, nhất định phải tắt máy đúng cách và kiểm tra rồi mới rời đi.\n💡 Mã QR sẽ biến mất sau một thời gian. Bấm biểu tượng làm mới ở góc dưới bên phải để tạo mã mới.\n💡 Vị trí và tên menu có thể hơi khác tùy phiên bản KakaoTalk trên điện thoại.\n\n📖 Bấm vào đây để xem hướng dẫn bằng hình.\n[[go:guide-print.html#store|Xem cách đưa tệp vào máy tính và in]]"}, "5": {"h": "1ijc50i", "q": "Có thể in trực tiếp từ điện thoại không?", "a": "📵 Không thể in trực tiếp từ điện thoại.\n\n💻 Máy tính cửa hàng có internet. Hãy làm thế này.\n1. Trước tiên gửi tệp trong điện thoại qua email hoặc KakaoTalk.\n2. Đăng nhập trên máy tính cửa hàng và tải tệp về.\n3. In tệp đã tải về.\n\n📖 Bấm vào đây để xem hướng dẫn bằng hình.\n[[go:guide-print.html#store|Xem cách in từ máy tính]]"}, "14": {"h": "vko1yv", "q": "Tôi có thể dùng giấy tự mang đến không?", "a": "❌ Không được. Chỉ được dùng giấy của cửa hàng.\nGiấy khác có thể làm lem màu hoặc bị kẹt trong máy in đa năng.\n\n📄 Giấy của cửa hàng\n- A4: Double A 75g\n- B4, A3: Hi-Plus 75g\n\n🙏 Dùng giấy mang đến có thể bị kẹt giấy hoặc làm hỏng máy. Nhất định hãy dùng giấy của cửa hàng."}, "3": {"h": "1ipawtz", "q": "Có in được khổ A3 không?", "a": "✅ Được, tất cả cửa hàng đều in·photo được khổ A4, B4, A3.\nCửa hàng ga Yeongtong (영통역점)\n🖨️ Máy số 1: chỉ A4\n🖨️ Máy số 2: A4, B4, A3\nCửa hàng ga Seojeongni (서정리역점)\n🖨️ Máy số 1: A4, B4, A3\n🖨️ Máy số 2: chỉ A4\nCác cửa hàng còn lại\n🖨️ Máy số 1: A4, B4\n🖨️ Máy số 2: A4, A3"}, "9": {"h": "1i3nrti", "q": "Số nhập ở máy in đa năng là gì?", "a": "🔢 Đó là mã PIN 4 số bạn đã nhập trên máy tính.\nMã PIN trên máy tính và số PIN ở máy in đa năng là một. Nó giống như mật khẩu tạm để tìm tài liệu bạn đã in từ máy tính. Nên dùng 4 số cuối số điện thoại của bạn.\n⚠️ Đừng dùng số ai cũng có thể dùng như 1234, 1111. Khi tìm ở máy in đa năng, tài liệu của người khác có thể hiện ra cùng.\n\n📜 Nếu chọn máy in chứng chỉ ([증명서전용PIN9999]) trên máy tính\n- Sẽ không hiện ô nhập mã PIN. Máy tự điền 9999 và gửi đến máy in đa năng.\n- Ở bước nhập số PIN trên máy in đa năng, hãy nhập 9999.\n- Khách khác cũng có thể đã dùng máy in chứng chỉ, nên tìm bằng 9999 có thể ra nhiều tài liệu. Hãy kiểm tra thời gian và tên tài liệu, chỉ thanh toán và in tài liệu của bạn.\n\n📖 Hướng dẫn bằng hình cách in chứng chỉ (TOEIC · TOEIC Speaking)\n[[go:guide-print.html#cert|Xem cách in chứng chỉ]]\n\n📖 Bấm vào đây để xem hướng dẫn bằng hình.\n[[go:guide-print.html#store|Xem cách nhập mã PIN]]"}, "13": {"h": "uo98e4", "q": "Dùng máy ép plastic và đóng sách nhiệt thế nào?", "a": "Có hai loại máy ép. Hãy xem cửa hàng có loại nào trước.\n⚫ Máy đen PL-1506 (chỉ để ép)\n⚪ Máy trắng SAFA-BM100 (ép · đóng sách 2 trong 1)\n\n👍 Nếu có cả hai loại, hãy dùng PL-1506 trước vì làm nóng và ép nhanh hơn.\n📖 Làm theo hướng dẫn cho máy ép của bạn ở menu trên cùng [사용방법] (Hướng dẫn) → [코팅] (Ép plastic).\n💰 Trước tiên kiểm tra còn bao nhiêu túi ép, và thanh toán trước.\n\n📚 Cách dùng đóng sách nhiệt\nĐóng sách nhiệt là cho giấy in vào bìa, dùng nhiệt làm chảy keo bên trong bìa để dán thành cuốn như sách. Không đục lỗ, không dùng lò xo. Đóng sách nhiệt làm bằng máy trắng 2 trong 1 (SAFA-BM100).\n1. Chọn bìa đóng nhiệt vừa với số tờ của bạn. Chỉ được cho vào đến số tờ ghi trên bìa.\n2. Thanh toán tiền bìa ở máy kiosk Toss. Mỗi bìa 1.500 won.\n3. Bấm nút nguồn, rồi bấm nút nhiệt [온열] một lần để làm nóng. Khoảng 3 phút sau có tiếng chuông và đèn ngừng nhấp nháy là đã nóng xong.\n4. Cho giấy ngay ngắn sao cho chạm vào keo bên trong bìa, rồi đẩy bìa, phần gáy trước, vào sâu trong khe dài phía trên.\n5. Bấm hẹn giờ và chờ.\n6. Xong thì lấy ra, để nguội từ 10 phút trở lên rồi mới mở.\n⚠️ Quá ít tờ (ví dụ 5 tờ, 10 tờ) thì không đóng được.\n\n📖 Bấm vào đây để xem hướng dẫn bằng hình.\n[[go:guide-coat.html#coat|Xem cách ép plastic]]\n[[go:guide-bind.html#bind|Xem cách đóng sách nhiệt]]"}, "36": {"h": "8k4fgt", "q": "Tôi muốn photo thẻ căn cước.", "a": "🆔 Thẻ căn cước được photo trên mặt kính.\n⛔ Đừng cho vào khay nạp bản gốc (ADF) phía trên máy in đa năng.\n\n1. Đặt thẻ cách góc trên bên trái mặt kính (mũi tên trắng) khoảng 5mm. Nếu sát góc, mép thẻ sẽ bị cắt mất.\n2. Đặt mặt có thông tin của thẻ úp xuống mặt kính. (nội dung hướng xuống)\n3. Trên màn hình máy, bấm [Copy], rồi ở thẻ [ID Copy] (Photo thẻ) chọn [Color] (màu) hoặc [Mono] (đen trắng).\n4. Original Size giữ nguyên [ID] rồi bấm [Start]. Đừng bấm nút [Passport] (Hộ chiếu).\n5. Khi hiện \"Do you want to scan another page?\" (Scan trang khác?):\n- Chỉ mặt trước: bấm [No] rồi thanh toán.\n- Cả mặt sau: lật thẻ lại ngay tại chỗ cũ, bấm [Yes] → bấm lại [Start] → thanh toán.\n\n⚠️ Chỉ photo vùng bằng kích thước thẻ. Đặt lệch một chút là sẽ bị cắt mất.\n❌ Tuyệt đối không photo hộ chiếu bằng [ID Copy] (Photo thẻ)! Chỉ một phần hộ chiếu được photo. Hộ chiếu phải dùng [Basic Copy] (Photo cơ bản).\n📌 Trên tường cạnh máy in đa năng có dán hướng dẫn [신분증 복사 방법] (Cách photo thẻ). Hãy làm theo.\n\n📖 Bấm vào đây để xem hướng dẫn bằng hình.\n[[go:guide-copy.html#idcard|Xem cách photo thẻ căn cước bằng hình]]"}, "37": {"h": "1ld761", "q": "Đặt bản gốc thế nào khi photo · scan · fax?", "a": "📄 Bản gốc tờ rời đặt vào 'khay nạp bản gốc (ADF)' phía trên máy in đa năng.\n[[sm:images/common/adf-feeder.jpg]]\n- Mỗi lần đặt được tối đa 100 tờ.\n- Đặt mặt có nội dung hướng lên trên.\n- A4 thì cạnh dài về bên trái, B4·A3 thì cạnh ngắn về bên trái.\n- Đẩy vào hết, và giữ thẳng bằng thanh chặn giấy trên · dưới.\n- Khi bắt đầu, bản gốc phải vào máy rồi ra lại mới là bình thường. Nếu không vào, hãy hủy và làm lại.\n\n📘 Những bản gốc dưới đây đặt từng tờ lên mặt kính.\n- Sách, thẻ căn cước, sổ ngân hàng, hộ chiếu\n- Giấy nhàu, giấy có dán ghi chú, giấy có ghim bấm\n- Trên mặt kính, căn theo mũi tên trắng ở góc trên bên trái. (Riêng thẻ căn cước thì cách góc khoảng 5mm.)\n- Đặt mặt có nội dung úp xuống mặt kính. (Ngược với ADF!)\n\n⚠️ Để tùy chọn hướng bản gốc là [세로] (Dọc) và đừng đổi. Nếu đổi, nội dung sẽ bị cắt.\n\n📖 Bấm vào đây để xem hướng dẫn bằng hình.\n[[go:guide-copy.html#adf|Xem cách dùng khay nạp bản gốc (ADF)]]\n[[go:guide-copy.html#glass|Xem cách đặt bản gốc lên mặt kính]]"}, "38": {"h": "1752u6k", "q": "Khi photo/scan trên mặt kính thì hiện \"Do you want to scan another page?\" (Scan trang khác?).", "a": "Thông báo này luôn hiện ra khi làm trên mặt kính.\n\n1. Nếu còn bản gốc: trước tiên đổi bản gốc trên mặt kính, rồi bấm [Yes] (Có).\n2. Nếu hết bản gốc: bấm [No] (Không).\n\n⚠️ Nếu bấm [Yes] (Có) mà không đổi bản gốc, cùng một trang sẽ bị scan mãi.\n💡 Nếu cửa sổ scan thêm không biến mất, hãy chuyển sang máy in đa năng bên cạnh để thử. Nếu vẫn không được, hãy báo qua TalkTalk. (Ngày thường 9 giờ sáng–9 giờ tối có thể gọi điện)\n\n📖 Bấm vào đây để xem hướng dẫn bằng hình.\n[[go:guide-copy.html#glass|Xem giải thích cửa sổ 'Scan trang khác?']]"}, "39": {"h": "1vi9u2c", "q": "Tệp đã scan ở đâu?", "a": "💻 Tệp đã scan nằm trên màn hình nền máy tính cửa hàng.\n- Scan ở máy số 1: thư mục [1번복합기스캔함] (thư mục scan máy số 1)\n- Scan ở máy số 2: thư mục [2번복합기스캔함] (thư mục scan máy số 2)\n\n📁 Có thể chọn loại tệp PDF hoặc JPG. (Không có PDF tìm kiếm được chữ)\n⏳ Tệp sẽ bị xóa 30 phút sau khi thanh toán. Khi tệp được tạo, hãy chuyển ngay sang chỗ khác.\n🔌 Nếu có USB thì chép vào USB, nếu không thì gửi qua internet vào email để mang đi.\n💰 Phí scan là 100 won mỗi mặt, không phân biệt khổ giấy hay màu·đen trắng.\n\n📖 Bấm vào đây để xem hướng dẫn bằng hình.\n[[go:guide-scan.html#scan|Xem cách tìm tệp đã scan]]"}, "40": {"h": "1kmcgfy", "q": "In 2 mặt có rẻ hơn không?", "a": "❌ In 2 mặt không làm giảm giá. Chỉ là giấy được in 2 mặt.\n- Màn hình thông tin thanh toán hiện toàn bộ số trang ban đầu.\n- In 2 mặt tính tiền như 2 mặt.\n\n⚠️ Tệp chỉ có 1 trang (ví dụ ảnh·hình) thì dù tăng số bản cũng không in 2 mặt được.\nMột tệp phải có từ 2 trang trở lên mới in 2 mặt được."}, "41": {"h": "1qgyrx8", "q": "In tệp từ USB hoặc tệp nén thế nào?", "a": "📂 Nhất định phải lưu tệp vào máy tính trước, rồi mới mở và in.\n- Nếu mở và in thẳng tệp trong USB, có thể ra giấy trắng.\n- Tệp nén (zip, v.v.) hãy giải nén rồi mới mở và in.\n- Lưu ra màn hình nền thì dễ tìm.\n\n🔍 Nếu không thấy tệp đã lưu\n- Tệp tải từ internet: [파일 탐색기] (File Explorer) → thư mục [다운로드] (Tải xuống)\n- Tệp nhận qua KakaoTalk: [파일 탐색기] (File Explorer) → [문서] (Tài liệu) → thư mục [카카오톡] (KakaoTalk)\n\n⚠️ Giấy trắng hoặc bị cắt do không làm theo hướng dẫn sẽ không được hoàn tiền.\n\n📖 Bấm vào đây để xem hướng dẫn bằng hình.\n[[go:guide-print.html#store|Xem cách lưu tệp vào máy tính và in]]"}, "42": {"h": "98zq57", "q": "Màn hình thông tin thanh toán hiện nội dung tôi không muốn.", "a": "🛑 Đừng thanh toán. Chỉ cần gửi lại từ máy tính.\n\n1. Đừng thanh toán ở máy in đa năng, để nguyên như vậy.\n2. Cài lại tùy chọn in trên máy tính.\n3. Đổi mã PIN sang số mới rồi in lại.\n4. Tìm bằng số mới ở máy in đa năng rồi thanh toán.\n\n💡 Danh sách chưa thanh toán sẽ tự xóa sau 30 phút.\n⚠️ Thanh toán mà không kiểm tra màn hình thông tin thanh toán thì không được hoàn tiền.\n\n📖 Bấm vào đây để xem hướng dẫn bằng hình.\n[[go:guide-print.html#ptips|Xem cách kiểm tra màn hình thông tin thanh toán]]\n[[go:guide-print.html#mfp|Xem cách thanh toán ở máy in đa năng]]"}, "43": {"h": "19klg4x", "q": "Danh sách trên máy in đa năng hiện nhiều tệp. Tôi nên chọn cái nào?", "a": "👀 Chỉ chọn và thanh toán tài liệu của bạn.\n- Chạm vào tài liệu trong danh sách, nó sẽ chuyển sang màu xanh. Có thể chọn nhiều cái.\n- Chọn xong, bấm [시작] (Bắt đầu). Chỉ những cái đã chọn được thanh toán và in cùng lúc.\n- Trước khi thanh toán, hãy đối chiếu thời gian và tên tệp để chắc chắn tài liệu trong danh sách là của bạn.\n- Tài liệu in ra do thanh toán mà không kiểm tra thì không được hoàn tiền.\n- Nếu đã dùng máy in chứng chỉ ([증명서전용PIN9999]), hãy tìm bằng 9999 rồi chọn tài liệu của bạn.\n\n⚠️ Cẩn thận với [모두인쇄] (In tất cả) ở góc trên bên phải!\nNếu bấm, mọi tệp trong danh sách sẽ được thanh toán và in cùng lúc. Chỉ bấm khi tất cả trong danh sách đều là của bạn.\nNếu không biết có tệp của người khác lẫn vào mà thanh toán luôn, cũng không được hoàn tiền.\n\n📖 Bấm vào đây để xem hướng dẫn bằng hình.\n[[go:guide-print.html#mfp|Xem cách chọn trong danh sách ở máy in đa năng]]"}, "44": {"h": "n6258s", "q": "Tôi có thể kết nối laptop của mình với máy in đa năng để in không?", "a": "❌ Không được. Không thể kết nối trực tiếp laptop cá nhân với máy in đa năng hay in qua Wi-Fi.\n\n👉 Hãy chuyển tệp sang PDF, chuyển qua USB hoặc email·KakaoTalk, rồi in từ máy tính cửa hàng."}, "45": {"h": "poizux", "q": "Có thể in tràn lề, không có lề không?", "a": "❌ Dù khổ giấy nào, bốn phía cũng có lề khoảng 5mm.\n\nMuốn in không lề, hãy dùng tiệm in chuyên nghiệp. 🙏"}, "46": {"h": "7bu9dc", "q": "Giá sử dụng là bao nhiêu?", "a": "💰 In · photo (mỗi mặt)\n- Đen trắng: A4 70 won, B4 120 won, A3 140 won\n- Màu: A4 250 won, B4 400 won, A3 500 won\n- In 2 mặt tính tiền như 2 mặt.\n\n📄 Scan: 100 won mỗi mặt (khổ nào cũng như nhau)\n📠 Fax: 500 won mỗi mặt (chỉ gửi đen trắng)\n✨ Ép plastic: A4 400 won/tờ, A3 800 won/tờ\n📚 Đóng sách nhiệt: 1.500 won mỗi bìa (dày mỏng như nhau)\n🛍️ Sản phẩm: bìa kẹp chữ L · bìa kẹp thanh trượt · phong bì tài liệu 600 won mỗi cái\n\n💡 Cũng có thể xem bảng giá ở menu [서비스] (Dịch vụ) của trang web.\n\n📖 Bấm vào đây để xem hướng dẫn bằng hình.\n[[go:services.html#price|Xem bảng giá]]"}, "30": {"h": "uasjtr", "q": "Cửa hàng có camera (CCTV) phải không? Tôi muốn xem video.", "a": "✅ Bạn có thể xem video vào khoảng thời gian bạn có mặt, sau khi xác minh danh tính.\n\n📹 2 cách xem video\n1. Xem trực tiếp\n- Gặp quản lý, xác minh danh tính rồi xem video.\n- Ngày giờ không phải do bạn tự chọn mà thỏa thuận với quản lý.\n2. Nghe qua điện thoại\n- Nếu khó gặp mặt, sau khi xác minh danh tính, chúng tôi sẽ báo ngắn gọn nội dung video qua điện thoại.\n⚠️ Yêu cầu xem video không có nghĩa là được kiểm tra ngay.\n\n💬 Cách đăng ký\nHãy gửi 3 điều sau qua Naver TalkTalk.\n1. Ngày và giờ của video bạn muốn xem\n2. 4 số cuối của thẻ đã thanh toán\n3. Mục đích xem video\nQuản lý sẽ liên hệ riêng sau khi kiểm tra.\n\n👥 Nếu video có cả người khác?\n- Chúng tôi che người khác để không nhận ra được (xử lý ẩn danh) rồi mới cho xem.\n- Người yêu cầu xem video trả chi phí che hình.\n\n⏳ Không xử lý ngay\nDù yêu cầu qua điện thoại hay TalkTalk, chúng tôi cũng không làm ngay được. Từ khi quản lý nhận yêu cầu đến khi kiểm tra video có thể mất vài ngày.\nQuản lý sẽ liên hệ riêng sau khi kiểm tra.\n\n📹 Có thể khó tìm bằng video\n- Video được lưu 10 ngày kể từ lúc quay. Dù trong thời hạn lưu, nếu máy chủ của công ty CCTV hoặc thiết bị xem có sự cố thì cũng có thể không xem được.\n- Có góc khuất, và những thứ như thẻ căn cước để bên trong máy scan có thể không nhìn thấy."}, "29": {"h": "18dzcsk", "q": "Tôi để quên thẻ căn cước·thẻ ngân hàng·USB ở cửa hàng. Có thể giữ giúp tôi không?", "a": "Đây là cửa hàng không người trực nên khó giữ giúp đồ để quên. 🙏\n\n🆔 Nếu bị mất thẻ căn cước·thẻ tín dụng\n1. Trước tiên liên hệ nơi cấp (công ty thẻ, v.v.) để báo mất hoặc khóa thẻ.\n2. Đến cửa hàng càng sớm càng tốt.\n3. Tìm quanh chỗ bạn đã ngồi.\n4. Nếu không thấy, hãy kiểm tra [분실물보관함] (Hộp đồ thất lạc) trông giống hộp thư trong cửa hàng.\n\n📮 Hộp đồ thất lạc được dùng như sau\n- Khách hoặc quản lý thấy đồ thì bỏ vào hộp.\n- Cũng có khách thấy mà không bỏ vào.\n- Điều này không có nghĩa là chúng tôi ghi sổ đồ thất lạc hay chịu trách nhiệm giữ đồ.\n- Đây là biện pháp tối thiểu để người khác không dùng thẻ căn cước·thẻ ngân hàng.\n\n🔒 Hộp được khóa bằng mật khẩu\n- Cách lấy mật khẩu được dán ở thông báo gần hộp. Hãy làm theo.\n- Nếu bị mất thẻ đã thanh toán ở cửa hàng và không biết thông tin thanh toán: hãy thanh toán mới ở cửa hàng bằng thẻ khác, rồi dùng giao dịch đó để lấy mật khẩu.\n- Nếu không có gì cần mua ở cửa hàng: hãy hỏi công ty thẻ thông tin thanh toán như số phê duyệt để lấy mật khẩu.\n\n⚠️ Quản lý không cho biết thông tin thanh toán cũ qua điện thoại.\nThủ tục phức tạp nên hãy cẩn thận để không làm mất đồ.\n\n🔒 Hộp đồ thất lạc được đặt để tiện cho khách. Chúng tôi không chịu trách nhiệm về việc giữ·trả lại·mất đồ.\n⛔ Đừng dùng hộp để gửi đồ của mình; hộp chỉ dành cho đồ thất lạc tìm thấy trong cửa hàng.\n💍 Đừng bỏ đồ giá trị như tiền mặt, trang sức vào.\n\n🔑 Cách lấy mật khẩu\n[[go:faq.html#faq-71|Xem cách dùng trang kiểm tra đồ thất lạc]]\n- Bấm biểu tượng [분실물확인] (Kiểm tra đồ thất lạc) trên màn hình nền máy tính cửa hàng.\n- Nhập thông tin thanh toán và số điện thoại, bạn sẽ nhận mật khẩu qua tin nhắn.\n- Nhất định phải tự làm. Quản lý không làm thay.\n- Kiểm tra hộp xong nhớ khóa lại cẩn thận.\n\n👮 Nếu biết có người lấy mất, hãy báo cảnh sát.\n\n⏳ Đồ không ai đến lấy trong thời gian dài có thể bị xử lý.\n\n⚖️ Luật liên quan (giải thích đơn giản)\n- Luật Đồ thất lạc, Điều 1: người nhặt được đồ phải trả cho chủ hoặc nộp cho đồn cảnh sát.\n- Bộ luật Dân sự, Điều 693: việc 'giữ hộ' đồ chỉ có khi người gửi và người nhận cùng thỏa thuận. Cửa hàng không người trực chưa từng thỏa thuận giữ đồ cho khách. Vì vậy khó yêu cầu quản lý cửa hàng tìm giúp.\n\n🚓 Hãy hỏi cả đồn cảnh sát\nĐồ nhặt được đôi khi được nộp cho cảnh sát. Có thể tìm trên cổng thông tin đồ thất lạc của Cảnh sát Lost112 (www.lost112.go.kr) hoặc gọi số 182."}, "21": {"h": "2iiqk7", "q": "Tôi đang dùng trang web giới hạn số lần in thì máy tính bị treo.", "a": "⚠️ Nếu máy tính gặp sự cố khi đang dùng các trang web dưới đây, chúng tôi không thể bồi thường.\n- Trang web thanh toán xong mới nhận được tài liệu\n- Trang web giới hạn số lần in\n- Trang web không lưu được tài liệu đã soạn\n(Trên máy tính cửa hàng cũng có dán thông báo.)\n\n🤔 Tại sao lại có sự cố?\n- Chúng tôi không chặn trang web cụ thể nào.\n- Nhưng chương trình bảo mật mà các trang đó cài đặt có thể xung đột với máy tính cửa hàng và gây ra sự cố.\n\n🔄 Khi máy tính cửa hàng khởi động lại, mọi chương trình đã tải và thông tin đăng nhập đều bị xóa. Hãy cẩn thận khi dùng trang web cần khởi động lại máy tính."}, "19": {"h": "u55pi7", "q": "Tôi định in bảng điểm TOEIC thì máy tính bị treo.", "a": "📜 Khi in chứng chỉ từ trang YBM (giấy chứng nhận điểm TOEIC · TOEIC Speaking · TOEFL) hoặc trang giấy chứng nhận tốt nghiệp·bảng điểm của trường dùng Certpia, nhất định chọn máy in [증명서전용PIN9999] (máy in chứng chỉ).\n(Không áp dụng cho trang Chính phủ 24 · Hometax · tòa án.)\n\n⚠️ Nếu chọn máy in màu hoặc đen trắng, máy tính sẽ bị treo và bạn có thể phải thanh toán lại để lấy chứng chỉ.\n\n1. Thanh toán trên trang web và nhận chứng chỉ.\n2. Khi mở tài liệu để in, chọn máy in [증명서전용PIN9999].\n3. Ở máy in đa năng, tìm mã PIN 9999 và thanh toán là sẽ in ra.\n\n💡 Mã PIN là số bạn đã nhập trên máy tính. Nó giống như mật khẩu tạm để tìm ở máy in đa năng tài liệu bạn gửi từ máy tính.\n\n❌ Chúng tôi không bồi thường thiệt hại tiền bạc do không làm theo hướng dẫn. (Trong cửa hàng cũng có dán thông báo.)\n\n📖 Bấm vào đây để xem hướng dẫn bằng hình.\n[[go:guide-print.html#cert|Xem cách in chứng chỉ]]"}, "23": {"h": "dds97b", "q": "Tệp Hangul bị lỗi chữ và lệch bố cục.", "a": "📄 Hangul trên máy tính cửa hàng là chương trình chỉ xem (trình xem).\nNếu máy tính cửa hàng không có phông chữ của máy đã làm tệp, chữ có thể bị lỗi, hiện ký hiệu lạ hoặc bố cục bị xô lệch.\n\n👉 Tệp Hangul hãy chuyển sang PDF rồi mang đến.\n\n👀 Trước khi in, nhất định kiểm tra chữ có bị lỗi, có ký hiệu lạ không.\n⚠️ Chúng tôi không chịu trách nhiệm cho bản in sai do in mà không kiểm tra.\nSự cố do khác phông chữ hoặc phiên bản chương trình không thể sửa ở cửa hàng.\n\n📖 Bấm vào đây để xem hướng dẫn bằng hình.\n[[go:guide-print.html#hancom|Xem cách in tệp Hangul]]"}, "20": {"h": "8q81g9", "q": "Không mở được tài liệu trên trang Đăng ký trực tuyến, Chính phủ 24 hoặc tòa án.", "a": "Trang web chính phủ và tài chính thường xuyên cập nhật bảo mật. Vì vậy có thể xung đột với Windows, trình duyệt và các chương trình khác trên máy tính cửa hàng.\n\n🙏 Trường hợp này cửa hàng không thể giúp được gì.\n⚠️ Chúng tôi không bồi thường cho sự cố xảy ra khi dùng các trang này. (Trên máy tính cửa hàng cũng có dán thông báo.)"}, "10": {"h": "7e89a7", "q": "Mở tệp Hangul thì thấy ký hiệu lạ (□).", "a": "Không phải lỗi máy đâu! 👌\nĐó là do phông chữ (kiểu chữ) của máy đã làm tệp khác với máy tính cửa hàng.\n\nMàn hình hiện thế nào sẽ in ra đúng như vậy.\n👉 Tệp Hangul hãy lưu thành PDF rồi mang đến.\n\n📖 Bấm vào đây để xem hướng dẫn bằng hình.\n[[go:guide-print.html#hancom|Xem cách in tệp Hangul]]"}, "57": {"h": "1gjckxk", "q": "Có sửa được tệp PDF hoặc Hangul không?", "a": "❌ PDF và Hangul (HWP) là chương trình chỉ xem (trình xem) nên không sửa được.\n\n💡 Tệp Hangul có thể sửa đơn giản bằng chương trình [한글편집(Polaris)] (Sửa Hangul Polaris) trên màn hình nền.\nNhưng tùy dung lượng hoặc phiên bản tệp, bố cục có thể bị vỡ.\n\n👉 Tệp cần sửa hãy sửa trước ở nhà rồi mang đến dạng PDF.\n\n📖 Bấm vào đây để xem hướng dẫn bằng hình.\n[[go:guide-print.html#hancom|Xem cách in tệp Hangul]]"}, "58": {"h": "1h21n0d", "q": "Có in được giấy chứng nhận từ Chính phủ 24 hoặc Hometax không? Còn chứng thư số thì sao?", "a": "✅ Được, có thể dùng các trang của cơ quan công như Chính phủ 24, Hometax. Cũng dùng được chứng thư số.\n\n🔑 Chứng thư số hãy mang theo trong USB hoặc chép vào máy tính để dùng. (Khởi động lại máy tính thì sẽ bị xóa)\n\n⚠️ Trang chính phủ·tài chính có nhiều chương trình bảo mật nên có thể xung đột với máy tính cửa hàng. Sự cố khi đó không được bồi thường.\n⚠️ Một số giấy chứng nhận có thể in ra trắng do dung lượng·định dạng tệp. Trước khi in nhất định kiểm tra bản xem trước.\n🆘 Chúng tôi khuyên không nên dùng tài liệu phải trả tiền mới nhận được hoặc tài liệu giới hạn số lần in.\n\n🚫 Tài liệu của Chính phủ 24 · Hometax · tòa án (Đăng ký trực tuyến) không dùng [증명서전용PIN9999] (máy in chứng chỉ).\n💳 Tiền bạn trả trên các trang này để cấp tài liệu không liên quan đến PrintShop Mini. Tiền của PrintShop Mini trả ở máy in đa năng, và tài liệu in ra sau cùng khi đã thanh toán.\n🖨️ Tài liệu nhận từ trang web hãy mở trên máy tính và gửi lệnh in, rồi thanh toán ở máy in đa năng.\n[[go:guide-print.html#store|Xem cách in]]"}, "59": {"h": "iht9xr", "q": "In tệp của chương trình đặc biệt như CAD thế nào?", "a": "❌ Máy tính cửa hàng không có các chương trình như CAD, Photoshop, Illustrator.\n\n👉 Hãy chuyển sang PDF ở nhà rồi mang đến.\n🖼️ Gộp nhiều hình thành một PDF bằng chương trình trên máy tính cửa hàng thì khó. Hãy dùng trang web bên ngoài hoặc làm sẵn rồi mang đến.\n📂 Nếu nhận PDF dạng tệp nén, hãy giải nén rồi mới in."}, "24": {"h": "1pfag4s", "q": "Tôi không có thẻ. Có thể trả bằng tiền mặt hoặc chuyển khoản không? (Nạp tiền trả trước ở kiosk Toss)", "a": "⚠️ Nếu có thẻ IC (tín dụng/ghi nợ) hoặc Samsung Pay, đừng thanh toán ở máy kiosk Toss!\n💳 Ở bước thanh toán, cắm thẻ IC vào máy quẹt thẻ của máy in đa năng, Samsung Pay thì áp trực tiếp.\n💸 Nếu thanh toán nhầm ở kiosk Toss rồi hoàn tiền, sẽ trừ phí trước khi trả lại.\n\n❌ Không nhận tiền mặt và chuyển khoản.\n🧾 Không có thẻ cũng không sao! Hãy thanh toán trước ở máy kiosk Toss bằng Apple Pay · Kakao Pay · Toss Pay · thanh toán nhanh QR, rồi dùng thẻ nạp tiền.\n\n🎬 Xem video trước\n[[vid:videos/guide-toss.mp4]]\n\n📍 Máy kiosk Toss ở đâu?\nỞ trên bàn đặt máy ép·đóng sách màu trắng (SAFA-BM100). Các sản phẩm như túi ép, bìa kẹp chữ L, phong bì tài liệu thường cũng để trên bàn này.\n[[img:images/faq/pay-toss-where.png]]\n\n🧮 Trước tiên kiểm tra giá ở máy in đa năng\n\n🖨️ Khi in\n1. 💻 Mở tệp cần in trên máy tính, làm đến bước nhập mã PIN (4 số).\n2. Ở máy in đa năng, bấm [인쇄] (In) → [PC] rồi nhập mã PIN.\n3. Chọn tài liệu của bạn và bấm [시작] (Bắt đầu), màn hình giá tiền sẽ hiện ra. Nhất định xem kỹ đen trắng/màu, số trang, số tiền và ghi nhớ.\n\n📋 Khi photo · scan · fax\n- Hãy xem hướng dẫn trước, kiểm tra bản gốc có mấy tờ, đen trắng hay màu để tính tiền.\n\n🏧 Thanh toán ở máy kiosk Toss\n1. Đến máy kiosk Toss và bấm [결제하기] (Thanh toán).\n[[img:images/faq/pay-toss-kiosk.png]]\n2. Bấm [선불충전] (Nạp tiền trả trước) ở các thẻ phía trên.\n[[img:images/faq/pay-toss-s1-tab.png]]\n3. Chọn giống hệt những gì bạn thấy ở máy in đa năng. Ví dụ) In đen trắng → [복사/인쇄-A4-흑백-1장] (Photo/In-A4-đen trắng-1 tờ), scan 1 tờ → [스캔-1장] (Scan-1 tờ)\n[[img:images/faq/pay-toss-s2-item.png]]\n4. Khi hiện \"안내를 받으셨습니까?\" (Bạn đã được hướng dẫn chưa?), bấm [예(안내를 받았습니다.)] (Có). Chỉnh số tờ bằng [+] [−].\n[[img:images/faq/pay-toss-s3-agree.png]]\n💡 Phải bấm [예] (Có) ở câu \"Bạn đã được hướng dẫn chưa?\" thì mới tiếp tục thanh toán được.\n💡 Nhưng không bắt buộc phải gọi cho quản lý mới dùng được nạp tiền trả trước. Nếu đã đọc và hiểu hướng dẫn này, cứ bấm [예] (Có) và tiếp tục mà không cần gọi.\n💡 Nếu vẫn chưa rõ, hãy hỏi quản lý qua điện thoại hoặc TalkTalk.\n💡 Ngay lúc thanh toán nạp tiền trả trước, số tiền sẽ được nạp vào thẻ nạp tiền treo ở máy quẹt thẻ của máy in đa năng.\n5. Bấm [바로 결제] (Thanh toán ngay), hoặc nếu còn món khác cần thanh toán thì bấm [담기] (Thêm vào giỏ) rồi vào giỏ hàng để thanh toán.\n[[img:images/faq/pay-toss-s4-direct.png]]\n6. Khi hiện \"이대로 결제할까요?\" (Thanh toán như vậy nhé?), bấm [○○원 결제하기] (Thanh toán ○○ won).\n[[img:images/faq/pay-toss-s5-confirm.png]]\n7. Chọn phương thức thanh toán: [애플·NFC] (Apple·NFC) hoặc [QR 간편결제] (Thanh toán nhanh QR). Các ứng dụng như Kakao Pay, Naver Pay thì bấm [QR 간편결제] (Thanh toán nhanh QR). (Samsung Pay thì thanh toán trực tiếp ở máy quẹt thẻ của máy in đa năng)\n[[img:images/faq/pay-toss-s6-method-v2.png]]\n8. Nếu đã bấm [QR 간편결제] (Thanh toán nhanh QR), hãy đưa mã QR thanh toán trên điện thoại vào màn hình kiosk Toss.\n[[img:images/faq/pay-toss-s7-qr.png]]\n💡 Khi làm cả đen trắng và màu, bấm [담기] (Thêm vào giỏ), thêm một món bằng [더 담기 +] (Thêm nữa +), rồi thanh toán một lần.\n\n💳 Chạm thẻ nạp tiền ở máy in đa năng\n1. Thanh toán xong, đến máy in đa năng. Photo · scan · fax thì đặt bản gốc theo hướng dẫn, làm xong bấm [확인] (Xác nhận) ở màn hình giá tiền.\n2. Khi nghe \"카드를 대 주세요\" (Hãy chạm thẻ), chạm chiếc thẻ trắng treo bằng dây ở máy quẹt thẻ, giống như thẻ T-money.\n[[img:images/faq/pay-card-terminal.png]]\n\n✅ Thanh toán xong, in·photo sẽ in ra, scan sẽ tạo tệp, fax sẽ chuyển bản gốc thành tệp và bắt đầu gửi.\n\n⚠️ Số tiền ở máy in đa năng và số tiền thanh toán ở kiosk Toss phải giống hệt nhau.\n⚠️ Tiền thanh toán ở kiosk Toss chỉ nằm trong thẻ nạp tiền 20 phút. Đừng thanh toán trước; hãy kiểm tra giá ở máy in đa năng rồi mới thanh toán.\n⚠️ Đừng thanh toán 2 lần. Thanh toán trùng chỉ được hoàn lại số tiền sau khi trừ phí.\n💡 Tiền thanh toán ở kiosk Toss chỉ hoàn vào tài khoản ngân hàng. Chi tiết xem câu 'Hoàn tiền được xử lý khi nào và như thế nào?'.\n\n📖 Muốn biết cách làm trước, hãy bấm vào đây.\n[[go:guide-print.html#store|Xem cách in]]\n[[go:guide-copy.html|Xem cách photo]]\n[[go:guide-scan.html|Xem cách scan]]\n[[go:guide-fax.html|Xem cách gửi fax]]"}, "67": {"h": "klpm2u", "q": "Có thể thanh toán bằng Kakao Pay·Naver Pay không? Làm thế nào?", "a": "✅ Có thể thanh toán ở máy kiosk Toss. Máy quẹt thẻ cạnh máy in đa năng chỉ nhận thẻ tín dụng·ghi nợ và Samsung Pay.\nCách làm khác nhau tùy dịch vụ bạn muốn dùng.\n\n🛍️ Khi thanh toán sản phẩm (túi ép · bìa đóng nhiệt · bìa kẹp chữ L · bìa kẹp thanh trượt · phong bì tài liệu)\n1. Bấm [결제하기] (Thanh toán) ở kiosk Toss và chọn sản phẩm.\n2. Ở phương thức thanh toán, bấm [QR 간편결제] (Thanh toán nhanh QR).\n3. Trên điện thoại, mở mã QR thanh toán trong ứng dụng Kakao Pay (hoặc Naver Pay).\n4. Đưa mã QR vào màn hình kiosk (camera phía trên).\n5. Chờ đến khi thanh toán xong.\n\n🖨️ Khi in · photo · scan · fax\n- Thanh toán bằng [선불충전] (Nạp tiền trả trước) ở kiosk Toss.\n- Bấm [QR 간편결제] (Thanh toán nhanh QR) ở phương thức thanh toán để dùng Kakao Pay · Naver Pay.\n- Có nhiều bước nên nhất định hãy xem hướng dẫn có hình. Chi tiết có trong 'Câu hỏi: Tôi không có thẻ. Có thể trả bằng tiền mặt hoặc chuyển khoản không? (Nạp tiền trả trước ở kiosk Toss)'."}, "31": {"h": "1dwusmx", "q": "Làm thế nào để được giảm phí gửi xe (đăng ký gửi xe)?", "a": "🅿️ Đăng ký giảm phí gửi xe ở '주차등록' (Đăng ký gửi xe).\n\n🚫 Cửa hàng không giảm phí gửi xe\n- Cửa hàng Gwonseon (권선점)\n- Cửa hàng ga Dongbaek (동백역점)\nHai cửa hàng này có bãi đỗ xe nhưng có thu phí.\nPrintShop Mini không giảm phí gửi xe ở đó. 🙏\n\n✅ Các cửa hàng khác hãy bấm vào hình dưới đây để đăng ký.\n\n📋 Mỗi cửa hàng có chính sách giảm phí gửi xe khác nhau!\nKhi chọn cửa hàng (chi nhánh) của bạn trên trang web, chính sách giảm phí của cửa hàng đó sẽ hiện ra.\nHãy đọc kỹ chính sách rồi mới đăng ký giảm phí.\n\n👇 Trang đăng ký gửi xe sẽ mở ra.\n[[btn:images/faq/btn-parking2.png|https://fax.printnuri.com/parking|Đi đăng ký gửi xe]]\n💻 Trên màn hình nền máy tính cửa hàng cũng có biểu tượng [주차할인] (Giảm phí gửi xe). Có thể đăng ký ở đó.\n\n📝 Hãy làm thế này\n1. Ở [지점명] (Tên cửa hàng), chọn cửa hàng bạn đỗ xe. Thông tin giảm phí (thời gian, điều kiện) của cửa hàng đó sẽ hiện ra. Hãy đọc kỹ.\n2. Ở [카드 구분] (Loại thẻ), chọn cách bạn đã thanh toán.\n   - Samsung Pay · Apple Pay · thanh toán ở kiosk (đóng sách · ép): nhập [승인번호(8자리)] (số phê duyệt 8 số).\n   - Thẻ tín dụng (thẻ vật lý): nhập [앞 4자리] (4 số đầu) và [뒤 4자리] (4 số cuối) của số thẻ.\n3. Nhập [차량번호(4자리)] (biển số xe, 4 số).\n4. Bấm [검색] (Tìm kiếm). Tìm xe có thể mất một chút thời gian. Hãy chờ đến khi màn hình thay đổi.\n5. Kiểm tra biển số, giờ vào và ảnh xe có đúng không.\n6. Bấm [주차할인적용] (Áp dụng giảm phí), khi hiện \"주차 할인권을 적용하시겠습니까?\" (Áp dụng phiếu giảm phí?) thì bấm [주차할인적용] thêm một lần nữa.\n7. Khi hiện \"주차 할인권이 등록되었습니다\" (Đã đăng ký phiếu giảm phí) là xong.\n\n🔎 Muốn biết cách xem số phê duyệt, hãy bấm vào đây.\n[[go:faq.html#faq-6|Cách xem số phê duyệt Samsung Pay · Apple Pay]]\n\n⚠️ Nếu hiện những màn hình này, hãy làm thế này\n- \"결제 정보를 찾을 수가 없습니다\" (Không tìm thấy thông tin thanh toán): kiểm tra lại cửa hàng, loại thẻ, số thẻ (số phê duyệt).\n- \"차량 정보를 찾을 수가 없습니다\" (Không tìm thấy thông tin xe): kiểm tra lại biển số xe.\n- \"결제하신 금액이 주차 할인을 받기 위한 최소 금액보다 적습니다\" (Số tiền thanh toán thấp hơn mức tối thiểu): xem số tiền tối thiểu trong thông tin giảm phí của cửa hàng bạn.\n- \"이미 주차 등록된 이력이 존재합니다\" (Đã có lịch sử đăng ký): đã đăng ký bằng cùng giao dịch này rồi.\n- \"등록이 실패하였습니다\" (Đăng ký thất bại): hãy báo qua TalkTalk như hướng dẫn dưới đây.\n\n⚠️ Nếu không đăng ký được trên trang web, đừng lái xe ra mà hãy báo qua TalkTalk. (Ngày thường 9 giờ sáng–9 giờ tối có thể gọi điện)\n✉️ Nội dung gửi qua TalkTalk\n1. Tên cửa hàng\n2. Số liên lạc\n3. 4 số cuối biển số xe\n4. Sự cố (lỗi trang đăng ký giảm phí gửi xe)\n⏳ Hãy chờ trong cửa hàng một chút trong lúc quản lý kiểm tra. Phí gửi xe phát sinh do lái xe ra trước mà không liên hệ thì cửa hàng không chịu trách nhiệm.\n💳 Nếu thanh toán nhiều lần bằng cùng một thẻ, có trường hợp có thể gộp lại để đăng ký. (Không gộp được nhiều thẻ khác nhau)"}, "6": {"h": "1h6dk6j", "q": "Tôi cần hóa đơn. Có lấy được không?", "a": "🧾 Có thể lấy hóa đơn ở '영수증신청' (Yêu cầu hóa đơn).\n👇 Bấm vào hình dưới đây sẽ mở trang yêu cầu hóa đơn.\n[[btn:images/faq/btn-receipt2.png|https://fax.printnuri.com/receipt|Đi yêu cầu hóa đơn]]\n💻 Trên màn hình nền máy tính cửa hàng cũng có biểu tượng [영수증신청] (Yêu cầu hóa đơn). Có thể yêu cầu ở đó.\n\n📝 Hãy làm thế này\n1. Ở [지점명] (Tên cửa hàng), chọn cửa hàng bạn đã thanh toán.\n2. Ở [결제일자] (Ngày thanh toán), chọn ngày đã thanh toán.\n3. Ở [카드 구분] (Loại thẻ), chọn cách bạn đã thanh toán.\n   - Samsung Pay · Apple Pay · thanh toán ở kiosk (đóng sách · ép): nhập [승인번호(8자리)] (số phê duyệt 8 số).\n   - Thẻ tín dụng (thẻ vật lý): nhập [앞 4자리] (4 số đầu) và [뒤 4자리] (4 số cuối) của số thẻ.\n4. Bấm [검색] (Tìm kiếm). Khi lịch sử thanh toán hiện ra, kiểm tra giao dịch cần hóa đơn.\n5. Chọn kiểu hóa đơn bạn muốn.\n   - Hóa đơn thẻ (hình ảnh)\n   - Bảng kê giao dịch (PDF)\n6. Nhập [고객명] (Tên khách) và [고객연락처] (Số liên lạc). Nếu cần, ghi thêm [비고] (Ghi chú).\n7. Bấm [발급하기] (Xuất), khi cửa sổ hiện ra thì bấm [다운로드] (Tải xuống) để lưu tệp. Chờ một chút trong lúc tạo tệp.\n\n🔎 Số phê duyệt xem ở đâu?\nNếu thanh toán bằng Samsung Pay, bấm vào giao dịch trong ứng dụng Samsung Pay. Số [승인번호] (số phê duyệt) 8 chữ số ở mục ③ sẽ hiện ra.\n[[img:images/faq/pay-approve-samsung.jpg]]\nNếu thanh toán bằng Apple Pay, hãy xem trong ứng dụng thẻ Hyundai như hình dưới đây.\n[[img:images/faq/pay-approve-apple.jpg]]\n\n⚠️ Nếu hiện \"결제 정보를 찾을 수가 없습니다\" (Không tìm thấy thông tin thanh toán), hãy kiểm tra lại cửa hàng, ngày thanh toán, số thẻ (số phê duyệt) rồi tìm lại.\n💡 Nếu thanh toán nhiều lần bằng cùng một thẻ, hóa đơn có thể được gộp lại."}, "70": {"h": "1io1wqd", "q": "Xem nhanh: trường hợp được và không được hoàn tiền", "a": "📝 Hãy biết trước điều này\n- Muốn hoàn tiền phải đăng ký [환불접수] (Đăng ký hoàn tiền). Không đăng ký thì không được hoàn tiền.\n- ⏰ Phải đăng ký trong vòng 5 ngày kể từ ngày xảy ra sự cố (tính cả thứ Bảy, Chủ nhật và ngày lễ). Chỉ những đăng ký trong 5 ngày mới được kiểm tra và xử lý. Quá 5 ngày sẽ không được hoàn tiền.\n- Đăng ký không có nghĩa là được hoàn tiền ngay. Quản lý kiểm tra, chỉ xử lý trường hợp đủ điều kiện, và báo kết quả riêng qua số liên lạc đã đăng ký.\n- Hãy để lại bản in bị lỗi ở cửa hàng khi đăng ký. Không để lại thì không được hoàn tiền.\n[[btn:images/faq/btn-refund2.png|https://fax.printnuri.com/refund|Đi đăng ký hoàn tiền]]\n💻 Cũng có thể đăng ký bằng biểu tượng [환불신청] (Đăng ký hoàn tiền) trên màn hình nền máy tính cửa hàng.\n\n✅ Trường hợp được hoàn tiền (xử lý sau khi quản lý kiểm tra)\n- Máy hỏng, kẹt giấy, lem mực\n- Ra giấy trắng do máy in đa năng hỏng\n- Xuất hiện sọc trắng dài\n- Màu bị lem\n- Một màu mà in ra như chuyển màu\n- In ra hình không liên quan đến bản gốc khắp trang\n- Đã thanh toán nhưng quá 10 phút vẫn không in ra (đừng thanh toán lại, hãy liên hệ trước)\n- Trang không in ra vì máy dừng với thông báo \"không có giấy\" (chỉ phần không in ra)\n- Đã chọn máy in màu mà in ra đen trắng (hủy một phần: tổng tiền trừ giá đen trắng)\n- Fax bị [전송실패] (Gửi thất bại) vì ghi sai số nhận (hủy thanh toán)\n- Không ép hay đóng sách được vì máy hỏng (chỉ hoàn túi ép, bìa đóng nhiệt chưa dùng)\n\n❌ Trường hợp không được hoàn tiền\n\n📌 Không đăng ký\n- Không đăng ký hoặc đã quá 5 ngày\n- Không để lại bản in\n- Rời cửa hàng mà không liên hệ\n\n📌 Không kiểm tra trước khi thanh toán\n- Thanh toán mà không xem màn hình thông tin thanh toán (đen trắng/màu, 2 mặt/1 mặt, khổ giấy, số trang, số tiền)\n- Thanh toán mà không kiểm tra có phải tài liệu của mình, hoặc dùng [모두인쇄] (In tất cả) thanh toán luôn cả tệp của người khác\n\n📌 Không xem hướng dẫn hoặc bản xem trước\n- Làm mà không xem hướng dẫn nên bị sai\n- Có thể thấy ở bản xem trước nội dung bị cắt nhưng vẫn in\n- In mà không kiểm tra màu·đen trắng ở bản xem trước (ví dụ: chọn máy in màu mà bản xem trước đen trắng vẫn in)\n- In tệp USB mà không lưu vào máy tính nên ra giấy trắng\n- Không lưu tệp nén vào máy tính, giải nén, rồi bấm đúp mở tệp đã giải nén để in\n- Không lưu tệp từ email · đám mây · ổ web vào máy tính rồi bấm đúp mở tệp đã lưu để in\n- Không tải tệp từ email · KakaoTalk về mà mở bằng cửa sổ xem trước nhỏ để in, nên chữ bị lỗi, bị cắt hoặc in ra sai\n\n📌 Tự đặt sai hoặc ghi sai\n- Đặt sai bản gốc nên ra giấy trắng hoặc bị cắt (photo · scan · fax)\n- Ghi sai số fax nhưng số đó là số fax đang dùng nên hiện [전송완료] (Đã gửi)\n\n📌 Màu khác (màu khác với bản gốc không được hoàn tiền vì bất kỳ lý do gì)\n- Khác với màu trên màn hình máy tính\n- Photo cùng bản gốc mà mỗi lần màu lại khác\n- Màu vàng·bạc ra tối, màu dạ quang không ra\n- Hình mờ không ra\n- Photo lại giấy đã in hoặc đã photo mà một phần không ra\n- Chữ bút chì ra mờ, tài liệu scan bị mờ\n\n📌 Khác\n- Màu dạ quang trong tệp Hangul không ra (trình xem Hangul không có chức năng bút dạ quang)\n- Giấy có chấm nhỏ (vết lốm đốm)\n- Giấy trong cuốn đóng nhiệt bị rơi ra (không chạm đều vào keo, không đẩy vào sâu hết, hoặc mở ra mà không để nguội 10 phút)\n\n📌 Thanh toán lại hoặc thanh toán trùng\n- Thấy không in ra nên thanh toán lại, rồi bản in trước đó in ra\n- Không chờ fax mà gửi lại nên thanh toán trùng\n- Sơ ý thanh toán trùng ở kiosk Toss (chỉ hoàn lại số tiền sau khi trừ phí)\n\n📌 Chứng chỉ · trang web chính phủ\n- Sự cố do máy tính xung đột khi dùng trang web thanh toán xong mới nhận tài liệu, trang giới hạn số lần in, hoặc trang của cơ quan chính phủ·tài chính\n- Máy tính bị treo vì không chọn máy in [증명서전용PIN9999] (máy in chứng chỉ) cho TOEIC, bảng điểm·giấy chứng nhận tốt nghiệp của trường, Certpia (phí cấp chứng chỉ không được hoàn)\n\n💳 Nếu đã thanh toán ở kiosk Toss\n- Không hủy được trên thẻ. Chúng tôi hoàn tiền vào tài khoản ngân hàng.\n- Khi đăng ký hoàn tiền, chọn lý do là [직접입력] (Nhập trực tiếp), rồi ghi tên ngân hàng, số tài khoản, tên chủ tài khoản.\n\n👇 Nếu đã đọc nội dung trên, hãy đăng ký hoàn tiền.\n[[btn:images/faq/btn-refund2.png|https://fax.printnuri.com/refund|Đi đăng ký hoàn tiền]]\n💻 Cũng có thể đăng ký bằng biểu tượng [환불신청] (Đăng ký hoàn tiền) trên màn hình nền máy tính cửa hàng.\n\n📖 Bấm vào đây để xem chi tiết hơn.\n[[go:faq.html#faq-12|In sai thì có được hoàn tiền không?]]\n[[go:faq.html#faq-54|Hoàn tiền được xử lý khi nào và như thế nào?]]\n[[go:faq.html#faq-18|Bản in bị sọc hoặc lem màu]]\n[[go:faq.html#faq-17|Đã chọn máy in màu nhưng in ra đen trắng]]"}, "26": {"h": "3cmfad", "q": "Sản phẩm tôi muốn mua không có trên kệ.", "a": "📦 Bìa kẹp chữ L, phong bì tài liệu, bìa kẹp thanh trượt, túi ép, bìa đóng nhiệt chỉ được thanh toán và dùng những cái đang bày trên kệ.\n\n🙏 Xin đừng tự ý lấy hàng tồn kho cất trong cửa hàng khi chưa được quản lý cho phép.\n\nNếu không có loại hoặc số lượng bạn muốn?\n- Chỉ dùng những gì đang bày.\n- Phần còn lại hãy đến mua vào hôm khác.\n\n🙏 Chúng tôi thường xuyên kiểm tra hàng trên kệ để bạn không bất tiện. Nhưng khó biết khi nào hàng sẽ hết, nên bạn có thể không mua được sản phẩm mong muốn. Mong bạn thông cảm."}, "27": {"h": "1kil8qq", "q": "Tôi đã thanh toán ở kiosk Toss. Có thể lấy sản phẩm khác cùng giá không?", "a": "🙏 Hãy lấy đúng sản phẩm bạn đã thanh toán.\n\nBìa kẹp chữ L, phong bì tài liệu, bìa kẹp thanh trượt hiện nay (năm 2026) cùng giá 600 won một cái. Nhưng chúng tôi cần kiểm tra hàng tồn nên khó cho đổi.\nVí dụ) Nếu đã thanh toán 1 bìa kẹp chữ L (600 won) ở Toss thì hãy lấy bìa kẹp chữ L. Xin đừng lấy phong bì hay bìa kẹp thanh trượt.\n\n🙋 Nếu thật sự cần đổi, hãy báo qua Naver TalkTalk.\n1. Quét mã QR Naver TalkTalk dán trong cửa hàng.\n2. Ghi lại tên cửa hàng, sản phẩm đã thanh toán, sản phẩm đã lấy thay.\nĐiều này giúp ích rất nhiều cho việc kiểm tra hàng tồn. 🙏\n\n📅 Giá dự kiến sẽ thay đổi từ năm 2027."}, "60": {"h": "1oyfi8h", "q": "Tôi đã đi mà quên thanh toán sản phẩm.", "a": "🙏 Sản phẩm phải thanh toán rồi mới lấy ra dùng. Quên thanh toán cũng không sao.\n\n👉 Nếu biết sau, hãy gửi những điều sau qua Naver TalkTalk.\n- Tên cửa hàng\n- Số liên lạc\n- Khoảng thời gian sử dụng\n- Loại và số lượng sản phẩm đã dùng\nQuản lý sẽ kiểm tra và hướng dẫn cách thanh toán.\n\n⚠️ Lấy mà không thanh toán có thể thành vấn đề pháp lý. Khi biết hãy báo ngay.\n💡 Hãy kiểm tra sản phẩm có sẵn không, thanh toán trước rồi mới lấy ra dùng."}, "72": {"h": "11czglw", "q": "Giờ mở cửa và thông tin vận hành cửa hàng (24 giờ · tư vấn điện thoại · Wi-Fi)", "a": "🏪 PrintShop Mini hoạt động như sau.\n\n⏰ Giờ mở cửa\n✅ Tất cả cửa hàng mở 24 giờ, 365 ngày, không nghỉ ngày nào.\n✅ Mở cửa cả ngày lễ, Tết, kỳ nghỉ dài và ngày nghỉ tạm thời.\n🤖 Đây là cửa hàng không người trực, không có nhân viên. Khách tự làm những việc cần thiết, nếu có sự cố hãy liên hệ qua điện thoại hoặc TalkTalk.\n\n📞 Giờ tư vấn qua điện thoại\n- Chỉ tư vấn qua điện thoại vào ngày thường (thứ 2–thứ 6) 9 giờ sáng–9 giờ tối.\n- Số điện thoại được ghi khắp cửa hàng như trên màn hình nền máy tính, màn hình.\n🚫 Thứ 7, Chủ nhật và ngày lễ không tư vấn qua điện thoại.\n💬 Ngoài giờ đó và thứ 7·Chủ nhật·ngày lễ, hãy liên hệ qua Naver TalkTalk.\n\n📝 Nội dung gửi qua TalkTalk\n1. Tên cửa hàng (ghi trên màn hình nền máy tính hoặc bảng thông báo cạnh máy tính)\n2. Số máy in đa năng\n3. Sự cố\n4. Số liên lạc\nQuản lý sẽ liên hệ sau khi kiểm tra.\n\n📍 Vị trí cửa hàng\nTìm '프린트샵미니 + tên cửa hàng' trên Naver sẽ thấy vị trí, tên tòa nhà, tầng và số điện thoại.\n\n🚫 Khi sử dụng hãy tuân thủ\n- Không được mang thú cưng vào cửa hàng.\n- Cũng không được mang đồ ăn vào.\nHãy giúp giữ cửa hàng sạch sẽ và an toàn. 🙏\n\n📶 Wi-Fi miễn phí\n- Tên Wi-Fi: Printshopmini\n- Mật khẩu: printshopmini\n- Hãy nhập đúng chữ hoa, chữ thường.\n💻 Máy tính cửa hàng cũng có internet.\n\n🏪 Chúng tôi chưa làm nhượng quyền. Tất cả cửa hàng PrintShop Mini hiện nay đều do công ty trực tiếp vận hành.\n\n📖 Muốn xem chi tiết hơn\n[[go:faq.html#faq-28|Cửa hàng có mở vào kỳ nghỉ dài, ngày nghỉ tạm thời không?]]\n[[go:faq.html#faq-61|Có thể hỏi qua điện thoại không?]]\n[[go:faq.html#faq-55|Có thể mang thú cưng hoặc đồ ăn vào cửa hàng không?]]\n[[go:faq.html#faq-62|Có dùng Wi-Fi ở cửa hàng được không?]]\n[[go:faq.html#faq-63|Có thể mở cửa hàng nhượng quyền không?]]"}, "12": {"h": "15c506n", "q": "In sai thì có được hoàn tiền không?", "a": "📝 Muốn hoàn tiền nhất định phải 'đăng ký hoàn tiền'!\nKhông đăng ký thì không được hoàn tiền.\n⏰ Phải đăng ký hoàn tiền trong vòng 5 ngày kể từ ngày xảy ra sự cố (tính cả thứ Bảy, Chủ nhật và ngày lễ). Chỉ những đăng ký trong 5 ngày mới được kiểm tra và xử lý. Quá hạn sẽ không được hoàn tiền.\n👇 Bấm vào hình dưới đây sẽ mở trang đăng ký hoàn tiền.\n[[btn:images/faq/btn-refund2.png|https://fax.printnuri.com/refund|Đi đăng ký hoàn tiền]]\n💻 Trên màn hình nền máy tính cửa hàng cũng có biểu tượng [환불신청] (Đăng ký hoàn tiền). Có thể đăng ký ở đó.\n\n✅ Được hoàn tiền·xử lý\nLỗi máy như máy in hỏng, kẹt giấy, lem mực, ra giấy trắng thì cửa hàng xử lý.\n(Ra giấy trắng chỉ tính khi máy in đa năng hỏng. Giấy trắng do người dùng làm sai thì không hoàn tiền.)\n\n❌ Khó hoàn tiền·in lại\n- Làm mà không xem hướng dẫn nên bị sai\n- Hiểu sai hướng dẫn nên làm sai\n- Sự cố do máy tính xung đột khi dùng trang web thanh toán xong mới nhận tài liệu, trang giới hạn số lần in, hoặc trang của cơ quan chính phủ·tài chính (không bồi thường và không hoàn tiền)\n- Phí đã trả để cấp chứng chỉ khi máy tính bị treo vì không chọn máy in [증명서전용PIN9999] (máy in chứng chỉ) trên trang TOEIC, bảng điểm·giấy chứng nhận tốt nghiệp của trường, Certpia (không hoàn tiền)\n- Nội dung bị cắt khi in (trường hợp có thể kiểm tra bằng bản xem trước)\n- Đã chọn máy in màu nhưng in ra đen trắng (chọn máy in màu thì bản xem trước phải có màu mới đúng. Bản xem trước đen trắng mà vẫn không đổi tùy chọn và in luôn, nên trả giá màu mà in ra đen trắng)\n- Chọn đen trắng nhưng nghĩ bản xem trước có màu thì sẽ in màu, rồi yêu cầu hoàn tiền vì không ra màu\n- In tệp USB mà không lưu vào máy tính nên ra giấy trắng\n- Không lưu tệp nén vào máy tính, giải nén, rồi bấm đúp mở tệp đã giải nén để in, nên một phần hoặc toàn bộ ra giấy trắng\n- Không lưu tệp từ email · đám mây · ổ web vào máy tính rồi bấm đúp mở tệp đã lưu để in, nên in ra sai\n- Trước khi thanh toán, màn hình thông tin thanh toán đã hiện đen trắng/màu, 2 mặt/1 mặt, khổ giấy, số trang, số tiền mà vẫn thanh toán không kiểm tra, rồi yêu cầu hoàn tiền vì in sai\n\n⚠️ Trước khi thanh toán nhất định kiểm tra màn hình thông tin thanh toán!\nTrước khi thanh toán lần cuối, máy in đa năng sẽ hiện màn hình thông tin thanh toán. Màn hình này hiện:\n- Đen trắng/màu\n- 2 mặt/1 mặt\n- Khổ giấy\n- Số trang\n- Số tiền\nNếu thanh toán mà không kiểm tra rồi in ra thì không được hoàn tiền.\n\n🤔 Ví dụ) Trên máy tính chỉ in 3 trang mà khi thanh toán ở máy in đa năng lại hiện 2.500 won. 3 trang đen trắng không thể nhiều như vậy.\n👉 Nếu số trang và số tiền khác với điều bạn biết, đừng thanh toán."}, "54": {"h": "uudtld", "q": "Hoàn tiền được xử lý khi nào và như thế nào?", "a": "📝 Hoàn tiền được xử lý sau khi bạn đăng ký hoàn tiền và quản lý kiểm tra.\n⏰ Phải đăng ký hoàn tiền trong vòng 5 ngày kể từ ngày xảy ra sự cố (tính cả thứ Bảy, Chủ nhật và ngày lễ). Chỉ những đăng ký trong 5 ngày mới được kiểm tra và xử lý. Quá hạn sẽ không được hoàn tiền.\n\n1. Đăng ký bằng biểu tượng [환불신청] (Đăng ký hoàn tiền) trên màn hình nền máy tính cửa hàng hoặc trên trang đăng ký hoàn tiền.\n2. Ghi các số cuối của thẻ, số tiền, thời gian và sự cố.\n3. Hãy để lại bản in bị lỗi ở cửa hàng khi đăng ký. (Không để lại thì không được hoàn tiền)\n4. Quản lý kiểm tra nội dung đã đăng ký.\n5. Nếu hoàn tiền được, thường được xử lý vào hôm sau. Nếu khó hủy trên thẻ, sẽ hoàn vào tài khoản ngân hàng.\n\nℹ️ Quản lý sẽ báo riêng có được hoàn tiền hay không qua số liên lạc đã đăng ký.\n💡 Nếu có lý do không thể để lại bản in, hãy hỏi quản lý qua Naver TalkTalk.\n\n💳 Tiền thanh toán ở kiosk Toss được hoàn như sau.\n- Không hủy thanh toán trên hệ thống được. Chúng tôi hoàn tiền vào tài khoản ngân hàng.\n- Khi đăng ký hoàn tiền, chọn lý do là [직접입력] (Nhập trực tiếp) rồi nhập tên ngân hàng, số tài khoản, tên chủ tài khoản.\n- Nếu bạn sơ ý thanh toán trùng ở kiosk Toss, chúng tôi gửi lại số tiền sau khi trừ phí. Tuyệt đối đừng thanh toán trùng.\n- Trên kiosk Toss có dán lưu ý, hãy đọc kỹ.\n[[btn:images/faq/btn-refund2.png|https://fax.printnuri.com/refund|Đi đăng ký hoàn tiền]]"}, "32": {"h": "124gtj7", "q": "Tôi muốn kiểm tra fax đã gửi.", "a": "📠 Tra cứu fax đã gửi ở '팩스확인' (Kiểm tra fax).\n🔎 Hãy nhập số fax của nơi nhận (số nhận).\n👇 Bấm vào hình sẽ mở trang web.\n[[btn:images/faq/btn-faxcheck2.png|https://fax.printnuri.com/webfax|Kiểm tra kết quả gửi fax]]\n💻 Trên màn hình nền máy tính cửa hàng cũng có biểu tượng [팩스확인] (Kiểm tra fax). Có thể kiểm tra ở đó.\n\n📝 Hãy làm thế này\n1. Ở [수신 번호] (Số nhận), nhập số của nơi nhận fax.\n2. Bấm [검색] (Tìm kiếm).\n3. Trong bảng, kiểm tra [전송 시간] (Giờ gửi), [전송 지점명] (Cửa hàng gửi), [수신 번호] (Số nhận), [페이지 수] (Số trang), [전송 결과] (Kết quả) và [수신 시간] (Giờ nhận).\n\n⏳ 1. Fax có thể đến chậm\nVì là fax qua internet nên chậm hơn fax qua đường điện thoại.\nCó thể mất thời gian tùy kết nối và số tờ.\n👍 Nếu nhiều tờ, hãy chia ra mỗi lần 30 tờ!\n⚠️ Nếu không chờ mà gửi lại sẽ bị thanh toán trùng. Thanh toán trùng không được hoàn tiền.\n\n🔍 2. Dù tra không ra gì cũng hãy chờ\nVì là fax qua internet nên tra cứu có thể hơi chậm.\nNếu nhập số nhận để tra mà không ra gì\n1. ⏰ Hãy tra lại sau 5–10 phút.\n2. ⛔ Đừng vì tra không ra mà gửi lại fax rồi thanh toán trùng!\n3. 💬 Hãy hỏi quản lý trước.\n   Gửi 2 điều sau qua Naver TalkTalk.\n   - Tên cửa hàng\n   - 4 số cuối của thẻ đã thanh toán\n4. ✅ Quản lý sẽ kiểm tra và hướng dẫn.\n\n📖 Bấm vào đây để xem hướng dẫn bằng hình.\n[[go:guide-fax.html#fax|Xem cách kiểm tra kết quả gửi fax]]"}, "35": {"h": "bte37a", "q": "Người nhận nói không nhận được fax.", "a": "\"Không nhận được\" có thể có hai nghĩa.\nTrước tiên hãy kiểm tra kết quả gửi trên trang kiểm tra fax. (Xem câu 'Tôi muốn kiểm tra fax đã gửi' ở trên)\n\n❌ 1. Không gửi được ([전송실패], Gửi thất bại)\nNếu trang kiểm tra fax hiện [전송실패] (Gửi thất bại), hãy làm theo thứ tự sau.\n\n🔢 ① Trước tiên kiểm tra lại số fax nhận có đúng không.\n\n✅ ② Nếu số đúng\nCó thể thất bại do sự cố kết nối tạm thời.\n- Bấm [재전송] (Gửi lại) trên trang kiểm tra fax.\n- ⚠️ Chỉ gửi lại được một lần.\n- Chờ một chút rồi kiểm tra lại kết quả gửi.\n\n❌ ③ Nếu bị [전송실패] (Gửi thất bại) vì sai số\n👉 Hãy đăng ký hoàn tiền. Chúng tôi sẽ hủy thanh toán.\n\n⚠️ Nhưng nếu nhập sai số mà số đó là số fax đang dùng nên hiện [전송완료] (Đã gửi), chúng tôi không thể hoàn tiền.\n\n📄 2. Người nhận nhận được trang trắng, hoặc nội dung bị cắt\nĐiều này xảy ra khi đặt bản gốc sai cách.\n\n📌 ADF là 'chỗ đặt bản gốc' ở phía trên máy in đa năng.\n[[sm:images/common/adf-feeder.jpg]]- Nhận được trang trắng\n  → Bản gốc phải đặt vào khay nạp (ADF) với mặt có nội dung hướng lên, nhưng lại đặt úp nội dung xuống.\n- Nội dung bị cắt\n  → Đã đặt nội dung hướng lên, nhưng cạnh ngắn của bản gốc lại về bên trái thay vì cạnh dài.\n\n📝 Trước tiên hãy đăng ký hoàn tiền.\n- Quản lý kiểm tra rồi báo riêng có được hoàn tiền hay không qua số liên lạc đã đăng ký.\n- Nếu khách đặt sai bản gốc, chúng tôi không thể hoàn tiền. (Vì bản gốc đã thành dữ liệu và đã gửi xong đến máy chủ fax)\n\n⏰ Phải đăng ký hoàn tiền trong vòng 5 ngày kể từ ngày xảy ra sự cố (tính cả thứ Bảy, Chủ nhật và ngày lễ). Chỉ những đăng ký trong 5 ngày mới được kiểm tra và xử lý. Quá hạn sẽ không được hoàn tiền.\n\n👇 Hãy đăng ký hoàn tiền bằng hình bên dưới.\n[[btn:images/faq/btn-refund2.png|https://fax.printnuri.com/refund|Đi đăng ký hoàn tiền]]\n💻 Cũng có thể đăng ký bằng biểu tượng [환불신청] (Đăng ký hoàn tiền) trên màn hình nền máy tính cửa hàng.\n\n📖 Bấm vào đây để xem hướng dẫn bằng hình.\n[[go:guide-fax.html#fax|Xem cách gửi fax]]"}, "28": {"h": "lcey4t", "q": "Cửa hàng có mở vào kỳ nghỉ dài, ngày nghỉ tạm thời không?", "a": "✅ Có, chúng tôi mở 24 giờ, 365 ngày, không nghỉ ngày nào.\n\nTất cả cửa hàng PrintShop Mini đều đã đăng ký trên Naver Smart Place.\n📍 Hãy tìm trên Naver để xem vị trí, tên tòa nhà, tầng rồi mới đến."}, "55": {"h": "9gvg1k", "q": "Có thể mang thú cưng hoặc đồ ăn vào cửa hàng không?", "a": "❌ Không được mang thú cưng vào cửa hàng.\n❌ Cũng không được mang đồ ăn vào.\n\nHãy giúp giữ cửa hàng sạch sẽ và an toàn. 🙏"}, "61": {"h": "1osr0op", "q": "Có thể hỏi qua điện thoại không?", "a": "📞 Số điện thoại được ghi khắp cửa hàng. (Màn hình nền máy tính, màn hình, v.v.)\n🔎 Hoặc tìm '프린트샵미니 + tên cửa hàng' trên Naver để thấy số điện thoại.\n📞 Nhưng chỉ tư vấn qua điện thoại vào ngày thường (thứ 2–thứ 6) 9 giờ sáng–9 giờ tối.\n🚫 Thứ 7, Chủ nhật và ngày lễ không tư vấn qua điện thoại.\n💬 Ngoài giờ đó và thứ 7·Chủ nhật·ngày lễ, hãy liên hệ qua Naver TalkTalk.\n\n📝 Nội dung gửi qua TalkTalk\n1. Tên cửa hàng\n2. Sự cố\n3. Số liên lạc\n\n💡 Tên cửa hàng ghi trên màn hình nền máy tính hoặc bảng thông báo cạnh máy tính.\n💡 Số điện thoại được ghi trong cửa hàng."}, "62": {"h": "16ey7fu", "q": "Có dùng Wi-Fi ở cửa hàng được không?", "a": "✅ Được, có Wi-Fi miễn phí.\n\n📶 Tên Wi-Fi: Printshopmini\n🔑 Mật khẩu: printshopmini\n\n💡 Hãy nhập đúng chữ hoa, chữ thường.\n💻 Máy tính cửa hàng cũng có internet."}, "68": {"h": "72v8pb", "q": "Đã thanh toán và đang in bình thường, bỗng hiện \"không có giấy\" và không in được.", "a": "😮 Đang in bình thường thì bỗng dừng và hiện \"không có giấy phù hợp\"?\nĐiều này xảy ra vì trong tệp PDF có trang khác khổ.\n\n🔎 Tại sao lại như vậy?\n- Có thể xảy ra dù khổ giấy trong danh sách trên máy trông đều đúng (A4·B4·A3).\n- Một trang nào đó trong PDF có thể không phải khổ A4·B4·A3.\n  Ví dụ) Trong tệp PDF 10 trang, một trong các trang 2–10 có khổ khác\n- Khi in đến trang đó, máy sẽ báo \"không có giấy phù hợp\".\n- Khó biết trước. Chỉ khi in thật mới biết.\n\n✅ Cách phòng tránh (nhất định làm trước khi in)\n1. Mở từng tệp PDF.\n2. Trong tùy chọn in, tìm 'PDF 페이지 크기에 따라 용지 소스 선택' (chọn nguồn giấy theo khổ trang PDF).\n3. Nhất định bỏ dấu chọn ở ô đó.\n4. Gửi lại lệnh in, bắt đầu từ phần chưa in ra.\n5. Đến máy in đa năng và thanh toán.\n💡 Khi gửi nhiều tệp cùng lúc, hãy bỏ dấu chọn ở tất cả các tệp PDF.\n\n💸 Đã thanh toán mà có phần không in ra?\n1. Đăng ký hoàn tiền bằng biểu tượng [환불신청] (Đăng ký hoàn tiền) trên màn hình nền máy tính.\n2. Ở số tiền thanh toán, ghi số tiền đã thực sự thanh toán.\n3. Ở số tiền hoàn, tính và ghi số tiền của phần không in ra.\n⏰ Phải đăng ký trong vòng 5 ngày kể từ ngày xảy ra sự cố (tính cả thứ Bảy, Chủ nhật và ngày lễ). Chỉ những đăng ký trong 5 ngày mới được kiểm tra và xử lý. Nếu không đăng ký hoặc đăng ký sau 5 ngày, sẽ không được hoàn tiền.\nℹ️ Đăng ký không có nghĩa là được hoàn tiền ngay. Quản lý kiểm tra, chỉ xử lý trường hợp đủ điều kiện, và báo kết quả qua số liên lạc đã đăng ký.\n\n📖 Bấm vào đây để xem hình cài đặt in PDF.\n[[go:guide-print.html#acrobat|Xem cài đặt in PDF]]"}, "71": {"h": "177vrg8", "q": "Lấy mật khẩu hộp đồ thất lạc thế nào? (Cách dùng trang kiểm tra đồ thất lạc)", "a": "🔑 Mật khẩu hộp đồ thất lạc được gửi qua tin nhắn ở '분실물확인' (Kiểm tra đồ thất lạc).\n👇 Bấm vào hình dưới đây sẽ mở trang kiểm tra đồ thất lạc.\n[[btn:images/faq/btn-lostfound2.png|https://fax.printnuri.com/lostfound|Đi kiểm tra đồ thất lạc]]\n💻 Cũng có thể mở bằng biểu tượng [분실물확인] (Kiểm tra đồ thất lạc) trên màn hình nền máy tính cửa hàng.\n\n⚠️ Nhất định phải tự làm. Quản lý không làm thay.\n💡 Chỉ kiểm tra được giao dịch trong 30 ngày gần nhất.\n💬 Tin nhắn chỉ gửi tối đa 3 lần một ngày. Nếu không nhận được, hãy kiểm tra cả hộp thư rác.\n\n📝 Hãy làm thế này\n1. Đọc thông báo ở trên cùng rồi bấm [동의합니다] (Tôi đồng ý).\n   - Chỉ kiểm tra và lấy đồ của mình, đồ khác hãy để lại vào hộp.\n   - Dùng xong nhất định khóa hộp, kiểm tra đã khóa rồi mới đi.\n   - Bạn có thể phải chịu trách nhiệm cho sự cố do để hộp mở rồi bỏ đi.\n2. Ở [지점명] (Tên cửa hàng), chọn cửa hàng.\n3. Chọn [분실하신 물건] (Đồ bị mất). (USB, thẻ tín dụng·ghi nợ, thẻ đăng ký cư trú, bằng lái xe, hộ chiếu, sổ ngân hàng, khác) Mục 'khác' thì tự ghi.\n4. Nhập [결제일자] (Ngày thanh toán), [결제시간] (Giờ thanh toán), [결제 금액] (Số tiền thanh toán). Đây là giao dịch bạn đã thanh toán ở cửa hàng này.\n5. Chọn [카드 구분] (Loại thẻ).\n   - Samsung Pay · Apple Pay · thanh toán ở kiosk (đóng sách · ép): nhập [승인번호(8자리)] (số phê duyệt 8 số).\n   - Thẻ tín dụng (thẻ vật lý): nhập [앞 4자리] (4 số đầu) và [뒤 4자리] (4 số cuối) của số thẻ.\n6. Nhập [연락처] (Số liên lạc). Chỉ ghi số, không có \"-\". (ví dụ: 01012345678)\n7. Bấm [비밀번호 요청] (Yêu cầu mật khẩu), mật khẩu hộp sẽ được gửi qua tin nhắn đến số điện thoại đã nhập.\n\n🔎 Muốn biết cách xem số phê duyệt, hãy bấm vào đây.\n[[go:faq.html#faq-6|Cách xem số phê duyệt Samsung Pay · Apple Pay]]\n\n⚠️ Nếu hiện những màn hình này, hãy làm thế này\n- \"결제 정보를 찾을 수가 없습니다\" (Không tìm thấy thông tin thanh toán): kiểm tra lại cửa hàng, ngày, giờ, số tiền, số thẻ (số phê duyệt).\n- \"문자 전송이 실패하였습니다\" (Gửi tin nhắn thất bại): kiểm tra lại số điện thoại.\n- \"SMS 전송횟수를 초과하였습니다\" (Vượt quá số lần gửi SMS): đã quá 3 lần trong ngày. Hãy xem hộp tin nhắn rác trên điện thoại.\n\n📖 Hộp đồ thất lạc là gì, và cần làm gì khi mất thẻ căn cước·thẻ ngân hàng, xem ở câu hỏi dưới đây.\n[[go:faq.html#faq-29|Tôi để quên thẻ căn cước·thẻ ngân hàng·USB ở cửa hàng. Có thể giữ giúp tôi không?]]"}, "63": {"h": "17eu0n4", "q": "Có thể mở cửa hàng nhượng quyền không?", "a": "Chúng tôi chưa làm kinh doanh nhượng quyền.\nTất cả cửa hàng PrintShop Mini hiện nay đều do công ty trực tiếp vận hành. 🏪"}, "73": {"h": "1ekyuew", "q": "Màn hình máy in đa năng hiện cửa sổ Error và khó bấm.", "a": "Cửa sổ này hiện ra khi bạn cầm vào viền màn hình, hoặc có đồ vật đặt trên màn hình.\n[[img:images/faq/touch-error.png]]\n⚠️ Lúc này màn hình khó bấm.\n\nHãy thử như sau.\n1. ✋ Bỏ tay ra khỏi viền màn hình.\n2. 📦 Lấy đi đồ vật đặt trên màn hình (điện thoại · ví · giấy).\n3. 👆 Bấm nút nhẹ nhàng bằng một ngón tay.\n\n❌ Đừng cầm hoặc tựa vào màn hình!"}, "74": {"h": "1d5q6ed", "q": "Máy quẹt thẻ báo cần khởi động lại ('재부팅'). Tôi không thanh toán được.", "a": "💳 Tắt rồi bật lại (khởi động lại) máy quẹt thẻ gắn bên cạnh máy in đa năng thì hầu hết sẽ được khắc phục.\n[[warn:⛔ Chỉ tắt rồi bật lại công tắc của máy quẹt thẻ! Tuyệt đối không tắt hay chạm vào nguồn điện của máy in đa năng!]]\n1. 👉 Hãy nhìn mặt bên phải của máy quẹt thẻ. Có một khoảng trống vừa một ngón tay.\n[[img:images/faq/card-reader-top.png]]\n2. ☝️ Đưa ngón tay vào khoảng trống đó sẽ chạm thấy một công tắc. Đó là công tắc nguồn của máy quẹt thẻ.\n[[img:images/faq/card-reader-side.png]]\n3. 🔄 Gạt công tắc sang một bên để tắt, rồi gạt lại để bật.\n4. ⏳ Chờ đến khi màn hình máy quẹt thẻ sáng lại.\n5. 🖨️ Thanh toán lại từ đầu trên máy in đa năng.\n6. 🔊 Kiểm tra đã nghe tiếng '카드를 대 주세요' (Vui lòng chạm thẻ), rồi chạm thẻ để thanh toán.\n\nNếu vẫn không được, hãy báo tên cửa hàng và số máy in đa năng qua Naver TalkTalk."}}, "cats": {"mini": {"name": "Chương trình riêng", "desc": "Gửi xe · hóa đơn · hoàn tiền · kiểm tra fax · đồ thất lạc (cách dùng trang riêng của PrintShop Mini)"}, "broken": {"name": "Sự cố", "desc": "Khi máy có vấn đề hoặc in ra bị sai"}, "use": {"name": "Cách dùng", "desc": "Khi muốn biết cách sử dụng"}, "buy": {"name": "Mua sản phẩm", "desc": "Bìa kẹp chữ L · phong bì tài liệu · bìa kẹp thanh trượt"}, "store": {"name": "Vận hành cửa hàng", "desc": "Giờ mở cửa · ngày lễ · thú cưng · điện thoại · Wi-Fi · nhượng quyền"}, "pc": {"name": "Chương trình máy tính", "desc": "Khi chương trình trên máy tính có vấn đề"}, "cmv3cynpb": {"name": "Đồ thất lạc", "desc": "Thẻ căn cước, thẻ ngân hàng, đồ khác"}, "cmv3djben": {"name": "Xem CCTV", "desc": "Xem camera, lưu video, gửi video"}}};
